import React from 'react';
import './Pages.css';
// Directly import the JSON file
import grantsData from '../data/grant_database_output.json';

const CalgaryGrantDirectory = () => {
  // Use the imported data directly - no need for state, useEffect, or fetch

  return (
    <div className="page">
      <div className="page-header">
        <h1>Calgary Grant Directory</h1>
        <p className="subtitle">
          Discover available grants and funding opportunities for organizations and initiatives in Calgary and Alberta
        </p>
      </div>
      
      <div className="page-content">
        <div className="directory-intro">
          <div className="card">
            <h3>📋 About This Directory</h3>
            <p>
              This directory compiles various grant opportunities available to organizations, non-profits, 
              and community groups in Calgary and across Alberta. Use the table below to explore funding options 
              that match your needs.
            </p>
          </div>
        </div>

        <div className="grants-table-container">
          <div className="table-header">
            <h2>Available Grants</h2>
            <p className="table-subtitle">
              Showing {grantsData.length} grant opportunities
            </p>
          </div>
          
          <div className="table-wrapper">
            <table className="grants-table">
              <thead>
                <tr>
                  <th className="col-title">Grant Title</th>
                  <th className="col-description">Description</th>
                  <th className="col-link">More Information</th>
                </tr>
              </thead>
              <tbody>
                {grantsData.map((grant, index) => (
                  <tr key={index} className="grant-row">
                    <td className="grant-title">
                      <strong>{grant.Title}</strong>
                    </td>
                    <td className="grant-description">
                      {grant.Description}
                    </td>
                    <td className="grant-link">
                      <a 
                        href={grant.URL} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="link-button"
                      >
                        Visit Website
                      </a>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="resources-section">
          <h2>Grant Application Tips</h2>
          <div className="resource-list">
            <div className="resource-item">
              <h4>📅 Start Early</h4>
              <p>Begin your application well before the deadline to allow time for reviews and revisions.</p>
            </div>
            <div className="resource-item">
              <h4>📝 Read Guidelines Carefully</h4>
              <p>Ensure your project aligns with the funder's objectives and follows all application requirements.</p>
            </div>
            <div className="resource-item">
              <h4>🎯 Be Specific</h4>
              <p>Clearly articulate your project's goals, methods, and expected outcomes with measurable targets.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CalgaryGrantDirectory;