import React from 'react';
import './Pages.css';
import { Link } from 'react-router-dom';

const GrantToolbox = () => {
  return (
    <div className="page">
      <div className="page-header">
        <h1>Grant Toolbox</h1>
        <p className="subtitle">Tools and resources for effective grant management and application</p>
      </div>
      
      <div className="page-content">
        <div className="card-grid">
          <div className="card">
            <h3>📋 Grant Application Notes</h3>
            <p>Here you will find all of my research on creating an effective Grant application.</p>
            <Link to="/grant-application-notes" className="card-btn card-btn-link">
    View Notes
  </Link>
          </div>

          <div className="card">
            <h3>📅 Calgary Grant Directory</h3>
            <p>A compiled directory of all the foundations and government programs that offer grants.</p>
            <Link to="/calgary-grant-directory" className="card-btn card-btn-link">
              Explore Directory
            </Link>
          </div>
          
          
          <div className="card">
            <h3>💰 Budget Template Generator</h3>
            <p>Create professional grant budgets with automated calculations and category templates.</p>
             <Link to="/budget-template-generator" className="card-btn card-btn-link">
    Use Generator
  </Link>
          </div>
          
          <div className="card">
            <h3>👾 Grant Application AI Builder</h3>
            <p>Build the fundamentals used for Grant Application using AI</p>
            <Link to="/grant-application-ai-builder" className="card-btn card-btn-link">
    Use AI Builder
  </Link>
          </div>
          
          
        </div>
        
        <div className="resources-section">
          <h2>Grant Writing Resources</h2>
          <div className="resource-list">
            <div className="resource-item">
              <h4>Grant Writing Best Practices</h4>
              <p>Tips for writing compelling narratives and demonstrating need effectively.</p>
            </div>
            <div className="resource-item">
              <h4>Budget Justification Examples</h4>
              <p>Sample justifications for common budget line items.</p>
            </div>
            <div className="resource-item">
              <h4>Evaluation Plan Templates</h4>
              <p>Framework for developing strong program evaluation plans.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GrantToolbox;