import React from 'react';
import './Pages.css';
import { Link } from 'react-router-dom';

const DatathonProjects = () => {
  return (
    <div className="page">
      <div className="page-header">
        <h1>Datathon Projects</h1>
        <p className="subtitle">Showcasing data science projects from datathon competitions</p>
      </div>
      
      <div className="page-content">
        <div className="card-grid">
          <div className="card">
            <h3>🏘️ Datathon 2026 Project</h3>
            <p>Mapping Short-Term Rentals and Housing Supply Pressure in Calgary</p>
            <Link to="/datathon-2026-secondary-suites" className="card-btn card-btn-link">
              View Project Details
            </Link>
          </div>

          
        </div>
      </div>
    </div>
  );
};

export default DatathonProjects;