import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import './Pages.css';

const BudgetTemplateGenerator = () => {
  const [budgetItems, setBudgetItems] = useState([]);
  const [total, setTotal] = useState(0);

  const budgetCategories = [
    'Personnel & Salaries',
    'Equipment & Supplies',
    'Travel & Transportation',
    'Materials & Printing',
    'Facility Costs',
    'Professional Services',
    'Administrative Costs',
    'Other Expenses'
  ];

  // Load from localStorage on component mount
  React.useEffect(() => {
    const savedBudget = localStorage.getItem('nonprofitBudget');
    if (savedBudget) {
      try {
        const parsedBudget = JSON.parse(savedBudget);
        setBudgetItems(parsedBudget.items || []);
        setTotal(parsedBudget.total || 0);
      } catch (error) {
        console.error('Error loading saved budget:', error);
      }
    }
  }, []);

  // Save to localStorage whenever budgetItems change
  React.useEffect(() => {
    const budgetData = {
      items: budgetItems,
      total: total,
      lastUpdated: new Date().toISOString()
    };
    localStorage.setItem('nonprofitBudget', JSON.stringify(budgetData));
  }, [budgetItems, total]);

  const addBudgetItem = () => {
    const newItem = {
      id: Date.now(),
      category: '',
      description: '',
      quantity: 1,
      unitCost: 0,
      totalCost: 0
    };
    setBudgetItems([...budgetItems, newItem]);
  };

  const updateBudgetItem = (id, field, value) => {
    const updatedItems = budgetItems.map(item => {
      if (item.id === id) {
        const updatedItem = { ...item, [field]: value };
        
        // Calculate total cost if quantity or unitCost changes
        if (field === 'quantity' || field === 'unitCost') {
          updatedItem.totalCost = updatedItem.quantity * updatedItem.unitCost;
        }
        
        return updatedItem;
      }
      return item;
    });
    
    setBudgetItems(updatedItems);
    calculateTotal(updatedItems);
  };

  const removeBudgetItem = (id) => {
    const filteredItems = budgetItems.filter(item => item.id !== id);
    setBudgetItems(filteredItems);
    calculateTotal(filteredItems);
  };

  const calculateTotal = (items) => {
    const newTotal = items.reduce((sum, item) => sum + item.totalCost, 0);
    setTotal(newTotal);
  };

  const downloadBudgetAsExcel = () => {
    // Your existing download code remains the same...
    const excelData = [
      ['Grant Budget Template', '', '', '', ''],
      ['Generated on:', new Date().toLocaleDateString(), '', '', ''],
      ['', '', '', '', ''],
      ['Category', 'Description', 'Quantity', 'Unit Cost ($)', 'Total Cost ($)'],
      ...budgetItems.map(item => [
        item.category,
        item.description,
        item.quantity,
        item.unitCost,
        item.totalCost
      ]),
      ['', '', '', '', ''],
      ['', '', '', 'TOTAL:', `$${total.toFixed(2)}`]
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(excelData);
    const colWidths = [
      { wch: 25 }, { wch: 40 }, { wch: 10 }, { wch: 15 }, { wch: 15 }
    ];
    worksheet['!cols'] = colWidths;

    // Your existing styling code...
    if (!worksheet['!merges']) worksheet['!merges'] = [];
    worksheet['!merges'].push({ s: { r: 0, c: 0 }, e: { r: 0, c: 4 } });

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Grant Budget');

    const fileName = `grant-budget-${new Date().getTime()}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  // NEW FUNCTION: Import Excel file
  const importBudgetFromExcel = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        
        // Get first worksheet
        const worksheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });
        
        // Find the start of actual data (skip headers)
        const headerRowIndex = jsonData.findIndex(row => 
          row && row[0] === 'Category' && row[1] === 'Description'
        );
        
        if (headerRowIndex === -1) {
          alert('Could not find budget data in the uploaded file. Please use a file exported from this app.');
          return;
        }

        // Extract budget items (skip header row and any summary rows)
        const importedItems = [];
        for (let i = headerRowIndex + 1; i < jsonData.length; i++) {
          const row = jsonData[i];
          // Stop if we hit empty row or summary row
          if (!row || row.length === 0 || (row[0] === '' && row[1] === '')) {
            break;
          }
          
          // Skip the total row
          if (row[3] === 'TOTAL:') {
            continue;
          }

          const [category, description, quantity, unitCost, totalCost] = row;
          
          // Validate we have basic data
          if (category && description) {
            importedItems.push({
              id: Date.now() + i, // Generate unique IDs
              category: category || '',
              description: description || '',
              quantity: parseInt(quantity) || 1,
              unitCost: parseFloat(unitCost) || 0,
              totalCost: parseFloat(totalCost) || (parseInt(quantity) || 1) * (parseFloat(unitCost) || 0)
            });
          }
        }

        if (importedItems.length > 0) {
          setBudgetItems(importedItems);
          calculateTotal(importedItems);
          alert(`Successfully imported ${importedItems.length} budget items!`);
        } else {
          alert('No valid budget items found in the file.');
        }
      } catch (error) {
        console.error('Error importing file:', error);
        alert('Error importing file. Please make sure it\'s a valid budget file exported from this app.');
      }
    };
    
    reader.onerror = () => {
      alert('Error reading file. Please try again.');
    };
    
    reader.readAsArrayBuffer(file);
    
    // Reset file input
    event.target.value = '';
  };

  // NEW FUNCTION: Clear localStorage and reset
  const resetBudget = () => {
    if (window.confirm('Are you sure you want to clear the current budget? This action cannot be undone.')) {
      setBudgetItems([]);
      setTotal(0);
      localStorage.removeItem('nonprofitBudget');
    }
  };

  // NEW FUNCTION: Export to JSON backup
  const exportToJson = () => {
    const budgetData = {
      items: budgetItems,
      total: total,
      exportDate: new Date().toISOString(),
      version: '1.0'
    };
    
    const dataStr = JSON.stringify(budgetData, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    
    const link = document.createElement('a');
    link.href = URL.createObjectURL(dataBlob);
    link.download = `budget-backup-${new Date().getTime()}.json`;
    link.click();
  };

  // NEW FUNCTION: Import from JSON backup
  const importFromJson = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const importedData = JSON.parse(e.target.result);
        
        if (importedData.items && Array.isArray(importedData.items)) {
          setBudgetItems(importedData.items);
          setTotal(importedData.total || 0);
          alert('Budget successfully restored from backup!');
        } else {
          alert('Invalid backup file format.');
        }
      } catch (error) {
        console.error('Error importing backup:', error);
        alert('Error importing backup file. Please make sure it\'s a valid backup from this app.');
      }
    };
    
    reader.readAsText(file);
    event.target.value = '';
  };

  return (
    <div className="page">
      <div className="page-header">
        <h1>Budget Template Generator</h1>
        <p className="subtitle">Create professional grant budgets with automated calculations</p>
      </div>
      
      <div className="page-content">
        {/* NEW: Import/Export Controls */}
        <div className="budget-controls">
          <button onClick={addBudgetItem} className="card-btn">
            + Add Budget Item
          </button>
          <button onClick={resetBudget} className="card-btn card-btn-secondary">
            Reset Budget
          </button>
          
          <div className="import-export-controls">
            <label htmlFor="excel-import" className="card-btn card-btn-secondary">
              📂 Import Excel
            </label>
            <input
              id="excel-import"
              type="file"
              accept=".xlsx,.xls"
              onChange={importBudgetFromExcel}
              style={{ display: 'none' }}
            />
            
            <label htmlFor="json-import" className="card-btn card-btn-secondary">
              📂 Import Backup
            </label>
            <input
              id="json-import"
              type="file"
              accept=".json"
              onChange={importFromJson}
              style={{ display: 'none' }}
            />
            
            <button onClick={exportToJson} className="card-btn card-btn-secondary">
              💾 Backup to JSON
            </button>
            
            <button onClick={downloadBudgetAsExcel} className="card-btn card-btn-primary">
              📊 Export to Excel
            </button>
          </div>
        </div>

        {/* Rest of your existing JSX remains the same */}
        <div className="budget-items">
          {budgetItems.map((item, index) => (
            <div key={item.id} className="budget-item card">
              <div className="budget-item-header">
                <h4>Item #{index + 1}</h4>
                <button 
                  onClick={() => removeBudgetItem(item.id)}
                  className="remove-btn"
                >
                  ×
                </button>
              </div>
              
              <div className="budget-item-fields">
                <div className="form-group">
                  <label>Category</label>
                  <select 
                    value={item.category}
                    onChange={(e) => updateBudgetItem(item.id, 'category', e.target.value)}
                  >
                    <option value="">Select a category</option>
                    {budgetCategories.map(category => (
                      <option key={category} value={category}>{category}</option>
                    ))}
                  </select>
                </div>
                
                <div className="form-group">
                  <label>Description</label>
                  <input 
                    type="text"
                    value={item.description}
                    onChange={(e) => updateBudgetItem(item.id, 'description', e.target.value)}
                    placeholder="Describe this expense..."
                  />
                </div>
                
                <div className="budget-numbers">
                  <div className="form-group">
                    <label>Quantity</label>
                    <input 
                      type="number"
                      value={item.quantity}
                      onChange={(e) => updateBudgetItem(item.id, 'quantity', parseInt(e.target.value) || 0)}
                      min="1"
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Unit Cost ($)</label>
                    <input 
                      type="number"
                      value={item.unitCost}
                      onChange={(e) => updateBudgetItem(item.id, 'unitCost', parseFloat(e.target.value) || 0)}
                      step="0.01"
                      min="0"
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Total Cost</label>
                    <div className="total-cost">
                      ${item.totalCost.toFixed(2)}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {budgetItems.length > 0 && (
          <div className="budget-summary card">
            <h3>Budget Summary</h3>
            <div className="total-amount">
              <strong>Total Budget: ${total.toFixed(2)}</strong>
            </div>
            <div className="download-info">
              <p>Your budget is automatically saved to your browser. You can also export it for backup or sharing.</p>
            </div>
          </div>
        )}

        {budgetItems.length === 0 && (
          <div className="empty-state card">
            <h3>Start Building Your Budget</h3>
            <p>Click "Add Budget Item" to begin, or import an existing budget file.</p>
            <ul className="budget-tips">
              <li>💡 Your work is automatically saved to your browser</li>
              <li>💡 Import Excel files previously exported from this app</li>
              <li>💡 Create JSON backups for long-term storage</li>
              <li>💡 Export to Excel for grant submissions</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default BudgetTemplateGenerator;