import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import { jsPDF } from 'jspdf';
import './Pages.css';

const DonationReceiptGenerator = () => {
  const [receipts, setReceipts] = useState([]);
  const [currentReceipt, setCurrentReceipt] = useState({
    id: Date.now(),
    receiptNumber: '',
    issueDate: new Date().toISOString().split('T')[0],
    donationDate: new Date().toISOString().split('T')[0],
    donorType: 'individual',
    donorName: '',
    donorAddress: '',
    donorCity: '',
    donorProvince: '',
    donorPostalCode: '',
    donationAmount: 0,
    donationType: 'cash',
    paymentMethod: 'cash',
    advantageProvided: false,
    advantageDescription: '',
    advantageValue: 0,
    eligibleAmount: 0,
    charityName: '',
    charityAddress: '',
    charityCity: '',
    charityProvince: '',
    charityPostalCode: '',
    charityRegistrationNumber: '',
    authorizedSignature: ''
  });

  const provinces = [
    'AB', 'BC', 'MB', 'NB', 'NL', 'NS', 'NT', 'NU', 'ON', 'PE', 'QC', 'SK', 'YT'
  ];

  const donationTypes = [
    'cash',
    'cheque',
    'credit card',
    'electronic transfer',
    'securities',
    'property',
    'other'
  ];

  // Load from localStorage on component mount
  React.useEffect(() => {
    const savedReceipts = localStorage.getItem('donationReceipts');
    if (savedReceipts) {
      try {
        const parsedReceipts = JSON.parse(savedReceipts);
        setReceipts(parsedReceipts.items || []);
      } catch (error) {
        console.error('Error loading saved receipts:', error);
      }
    }
  }, []);

  // Save to localStorage whenever receipts change
  React.useEffect(() => {
    const receiptData = {
      items: receipts,
      lastUpdated: new Date().toISOString()
    };
    localStorage.setItem('donationReceipts', JSON.stringify(receiptData));
  }, [receipts]);

  const updateCurrentReceipt = (field, value) => {
    const updatedReceipt = { ...currentReceipt, [field]: value };
    
    // Calculate eligible amount if donation amount or advantage value changes
    if (field === 'donationAmount' || field === 'advantageValue') {
      const donationAmt = parseFloat(updatedReceipt.donationAmount) || 0;
      const advantageVal = parseFloat(updatedReceipt.advantageValue) || 0;
      updatedReceipt.eligibleAmount = Math.max(0, donationAmt - advantageVal);
    }
    
    // Auto-generate receipt number if empty
    if (field === 'donorName' && !updatedReceipt.receiptNumber) {
      const initials = updatedReceipt.donorName.split(' ').map(n => n[0]).join('').toUpperCase();
      updatedReceipt.receiptNumber = `${initials}-${new Date().getFullYear()}-${Date.now().toString().slice(-4)}`;
    }

    setCurrentReceipt(updatedReceipt);
  };

  const saveReceipt = () => {
    if (!currentReceipt.donorName || !currentReceipt.donationAmount) {
      alert('Please fill in at least donor name and donation amount.');
      return;
    }

    const receiptToSave = {
      ...currentReceipt,
      id: currentReceipt.id || Date.now(),
      savedDate: new Date().toISOString()
    };

    const existingIndex = receipts.findIndex(r => r.id === receiptToSave.id);
    let updatedReceipts;

    if (existingIndex >= 0) {
      // Update existing receipt
      updatedReceipts = receipts.map((r, i) => i === existingIndex ? receiptToSave : r);
    } else {
      // Add new receipt
      updatedReceipts = [...receipts, receiptToSave];
    }

    setReceipts(updatedReceipts);
    
    // Reset form for new receipt (but keep charity info)
    setCurrentReceipt(prev => ({
      id: Date.now(),
      receiptNumber: '',
      issueDate: new Date().toISOString().split('T')[0],
      donationDate: new Date().toISOString().split('T')[0],
      donorType: 'individual',
      donorName: '',
      donorAddress: '',
      donorCity: '',
      donorProvince: '',
      donorPostalCode: '',
      donationAmount: 0,
      donationType: 'cash',
      paymentMethod: 'cash',
      advantageProvided: false,
      advantageDescription: '',
      advantageValue: 0,
      eligibleAmount: 0,
      // Keep charity information
      charityName: prev.charityName,
      charityAddress: prev.charityAddress,
      charityCity: prev.charityCity,
      charityProvince: prev.charityProvince,
      charityPostalCode: prev.charityPostalCode,
      charityRegistrationNumber: prev.charityRegistrationNumber,
      authorizedSignature: prev.authorizedSignature
    }));

    alert('Receipt saved successfully!');
  };

  const loadReceipt = (receipt) => {
    setCurrentReceipt({ ...receipt });
  };

  const deleteReceipt = (id) => {
    if (window.confirm('Are you sure you want to delete this receipt?')) {
      const filteredReceipts = receipts.filter(receipt => receipt.id !== id);
      setReceipts(filteredReceipts);
    }
  };

  const generatePDF = (receipt = currentReceipt) => {
    const pdf = new jsPDF();
    
    // Title
    pdf.setFontSize(16);
    pdf.setFont('helvetica', 'bold');
    pdf.text('OFFICIAL DONATION RECEIPT FOR INCOME TAX PURPOSES', 105, 20, { align: 'center' });
    
    // Charity Information
    pdf.setFontSize(10);
    pdf.setFont('helvetica', 'bold');
    pdf.text('CHARITY INFORMATION:', 20, 40);
    pdf.setFont('helvetica', 'normal');
    pdf.text(`Name: ${receipt.charityName || '[Charity Name]'}`, 20, 47);
    pdf.text(`Address: ${receipt.charityAddress || '[Charity Address]'}`, 20, 54);
    pdf.text(`City: ${receipt.charityCity || '[City]'}`, 20, 61);
    pdf.text(`Province: ${receipt.charityProvince || '[Province]'}`, 80, 61);
    pdf.text(`Postal Code: ${receipt.charityPostalCode || '[Postal Code]'}`, 120, 61);
    pdf.text(`Registration Number: ${receipt.charityRegistrationNumber || '[CRA Registration Number]'}`, 20, 68);
    
    // Donor Information
    pdf.setFont('helvetica', 'bold');
    pdf.text('DONOR INFORMATION:', 20, 85);
    pdf.setFont('helvetica', 'normal');
    pdf.text(`Name: ${receipt.donorName}`, 20, 92);
    pdf.text(`Address: ${receipt.donorAddress}`, 20, 99);
    pdf.text(`City: ${receipt.donorCity}`, 20, 106);
    pdf.text(`Province: ${receipt.donorProvince}`, 80, 106);
    pdf.text(`Postal Code: ${receipt.donorPostalCode}`, 120, 106);
    
    // Receipt Details
    pdf.setFont('helvetica', 'bold');
    pdf.text('RECEIPT DETAILS:', 20, 123);
    pdf.setFont('helvetica', 'normal');
    pdf.text(`Receipt Number: ${receipt.receiptNumber}`, 20, 130);
    pdf.text(`Date of Issue: ${receipt.issueDate}`, 20, 137);
    pdf.text(`Date of Donation: ${receipt.donationDate}`, 20, 144);
    pdf.text(`Donation Type: ${receipt.donationType}`, 20, 151);
    pdf.text(`Payment Method: ${receipt.paymentMethod}`, 100, 151);
    
    // Amounts
    pdf.setFont('helvetica', 'bold');
    pdf.text('AMOUNTS:', 20, 168);
    pdf.setFont('helvetica', 'normal');
    pdf.text(`Total Donation Amount: $${parseFloat(receipt.donationAmount).toFixed(2)}`, 20, 175);
    
    if (receipt.advantageProvided && receipt.advantageValue > 0) {
      pdf.text(`Advantage Provided: ${receipt.advantageDescription}`, 20, 182);
      pdf.text(`Value of Advantage: $${parseFloat(receipt.advantageValue).toFixed(2)}`, 20, 189);
    }
    
    pdf.setFont('helvetica', 'bold');
    pdf.text(`Eligible Amount of Donation: $${parseFloat(receipt.eligibleAmount).toFixed(2)}`, 20, 200);
    
    // Footer and signature
    pdf.setFont('helvetica', 'normal');
    pdf.text('This official donation receipt is for income tax purposes.', 105, 220, { align: 'center' });
    pdf.text('The eligible amount is the amount that can be claimed on your tax return.', 105, 227, { align: 'center' });
    
    pdf.text('Authorized Signature: ________________________', 20, 250);
    pdf.text(`Date: ${receipt.issueDate}`, 20, 257);
    
    pdf.text('CRA requires that you keep this receipt with your tax records.', 105, 270, { align: 'center' });
    
    // Save PDF
    pdf.save(`donation-receipt-${receipt.receiptNumber}.pdf`);
  };

  const generatePrintableHTML = (receipt = currentReceipt) => {
    const printWindow = window.open('', '_blank');
    printWindow.document.write(`
      <!DOCTYPE html>
      <html>
      <head>
        <title>Donation Receipt - ${receipt.receiptNumber}</title>
        <style>
          body { font-family: Arial, sans-serif; margin: 40px; line-height: 1.4; }
          .header { text-align: center; margin-bottom: 30px; border-bottom: 2px solid #333; padding-bottom: 10px; }
          .section { margin-bottom: 25px; }
          .section-title { font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid #ccc; }
          .amounts { background: #f9f9f9; padding: 15px; border-radius: 5px; }
          .total-amount { font-size: 18px; font-weight: bold; margin-top: 10px; }
          .footer { margin-top: 40px; border-top: 1px solid #333; padding-top: 20px; }
          @media print { body { margin: 20px; } }
        </style>
      </head>
      <body>
        <div class="header">
          <h1>OFFICIAL DONATION RECEIPT FOR INCOME TAX PURPOSES</h1>
        </div>
        
        <div class="section">
          <div class="section-title">CHARITY INFORMATION</div>
          <div><strong>Name:</strong> ${receipt.charityName || '[Charity Name]'}</div>
          <div><strong>Address:</strong> ${receipt.charityAddress || '[Charity Address]'}</div>
          <div><strong>City:</strong> ${receipt.charityCity || '[City]'} 
               <strong>Province:</strong> ${receipt.charityProvince || '[Province]'} 
               <strong>Postal Code:</strong> ${receipt.charityPostalCode || '[Postal Code]'}</div>
          <div><strong>Registration Number:</strong> ${receipt.charityRegistrationNumber || '[CRA Registration Number]'}</div>
        </div>
        
        <div class="section">
          <div class="section-title">DONOR INFORMATION</div>
          <div><strong>Name:</strong> ${receipt.donorName}</div>
          <div><strong>Address:</strong> ${receipt.donorAddress}</div>
          <div><strong>City:</strong> ${receipt.donorCity} 
               <strong>Province:</strong> ${receipt.donorProvince} 
               <strong>Postal Code:</strong> ${receipt.donorPostalCode}</div>
        </div>
        
        <div class="section">
          <div class="section-title">RECEIPT DETAILS</div>
          <div><strong>Receipt Number:</strong> ${receipt.receiptNumber}</div>
          <div><strong>Date of Issue:</strong> ${receipt.issueDate}</div>
          <div><strong>Date of Donation:</strong> ${receipt.donationDate}</div>
          <div><strong>Donation Type:</strong> ${receipt.donationType}</div>
          <div><strong>Payment Method:</strong> ${receipt.paymentMethod}</div>
        </div>
        
        <div class="section amounts">
          <div class="section-title">AMOUNTS</div>
          <div><strong>Total Donation Amount:</strong> $${parseFloat(receipt.donationAmount).toFixed(2)}</div>
          ${receipt.advantageProvided && receipt.advantageValue > 0 ? 
            `<div><strong>Advantage Provided:</strong> ${receipt.advantageDescription}</div>
             <div><strong>Value of Advantage:</strong> $${parseFloat(receipt.advantageValue).toFixed(2)}</div>` : ''}
          <div class="total-amount">Eligible Amount of Donation: $${parseFloat(receipt.eligibleAmount).toFixed(2)}</div>
        </div>
        
        <div class="footer">
          <p>This official donation receipt is for income tax purposes. The eligible amount is the amount that can be claimed on your tax return.</p>
          <div style="margin-top: 30px;">
            <div>Authorized Signature: ________________________</div>
            <div>Date: ${receipt.issueDate}</div>
          </div>
          <p style="margin-top: 20px; font-style: italic;">CRA requires that you keep this receipt with your tax records.</p>
        </div>
        
        <script>
          window.onload = function() { window.print(); }
        </script>
      </body>
      </html>
    `);
    printWindow.document.close();
  };

  const exportReceiptsAsExcel = () => {
    const excelData = [
      ['Donation Receipts Export', '', '', '', '', '', ''],
      ['Generated on:', new Date().toLocaleDateString(), '', '', '', '', ''],
      ['', '', '', '', '', '', ''],
      ['Receipt Number', 'Donor Name', 'Donation Date', 'Donation Amount', 'Eligible Amount', 'Donation Type', 'Payment Method'],
      ...receipts.map(receipt => [
        receipt.receiptNumber,
        receipt.donorName,
        receipt.donationDate,
        receipt.donationAmount,
        receipt.eligibleAmount,
        receipt.donationType,
        receipt.paymentMethod
      ]),
      ['', '', '', '', '', '', ''],
      ['', '', '', 'Total Receipts:', receipts.length, '', '']
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(excelData);
    const colWidths = [
      { wch: 20 }, { wch: 25 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 15 }
    ];
    worksheet['!cols'] = colWidths;

    if (!worksheet['!merges']) worksheet['!merges'] = [];
    worksheet['!merges'].push({ s: { r: 0, c: 0 }, e: { r: 0, c: 6 } });

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Donation Receipts');

    const fileName = `donation-receipts-${new Date().getTime()}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  const downloadCompleteTemplate = () => {
    const charityInfo = {
      name: 'Community Hope Foundation',
      address: '123 Charity Lane',
      city: 'Toronto',
      province: 'ON',
      postalCode: 'M5V 1A1',
      registration: '123456789RR0001',
      signature: 'Jane Smith'
    };

    const testData = [
      // Headers
      ['Receipt Number', 'Donor Name', 'Donor Type', 'Donor Address', 'Donor City', 'Donor Province', 'Donor Postal Code', 'Donation Date', 'Donation Amount', 'Donation Type', 'Payment Method', 'Advantage Provided', 'Advantage Description', 'Advantage Value', 'Eligible Amount', 'Charity Name', 'Charity Address', 'Charity City', 'Charity Province', 'Charity Postal Code', 'Charity Registration Number', 'Authorized Signature'],
      
      // Sample data - all with same charity info
      ['JS-2024-1234', 'John Smith', 'individual', '123 Maple St, Toronto', 'Toronto', 'ON', 'M5V 2T1', '2024-01-15', 250, 'cash', 'cash', 'FALSE', '', 0, 250, charityInfo.name, charityInfo.address, charityInfo.city, charityInfo.province, charityInfo.postalCode, charityInfo.registration, charityInfo.signature],
      
      ['SC-2024-5678', 'Sarah Chen', 'individual', '456 Oak Avenue, Vancouver', 'Vancouver', 'BC', 'V6B 2T2', '2024-01-20', 500, 'credit card', 'Visa', 'TRUE', 'Complimentary dinner', 25, 475, charityInfo.name, charityInfo.address, charityInfo.city, charityInfo.province, charityInfo.postalCode, charityInfo.registration, charityInfo.signature],
      
      ['GT-2024-9012', 'GreenTech Inc.', 'corporation', '789 Corporate Blvd, Calgary', 'Calgary', 'AB', 'T2P 3G7', '2024-02-01', 1000, 'electronic transfer', 'E-transfer', 'FALSE', '', 0, 1000, charityInfo.name, charityInfo.address, charityInfo.city, charityInfo.province, charityInfo.postalCode, charityInfo.registration, charityInfo.signature],
      
      ['MR-2024-3456', 'Maria Rodriguez', 'individual', '101 Pine Road, Montreal', 'Montreal', 'QC', 'H3A 1T1', '2024-02-10', 150, 'cheque', 'Cheque #1234', 'FALSE', '', 0, 150, charityInfo.name, charityInfo.address, charityInfo.city, charityInfo.province, charityInfo.postalCode, charityInfo.registration, charityInfo.signature],
      
      ['DK-2024-7890', 'David Kim', 'individual', '202 Birch Lane, Ottawa', 'Ottawa', 'ON', 'K1P 5G7', '2024-02-15', 750, 'securities', 'Stock transfer', 'TRUE', 'Recognition plaque', 50, 700, charityInfo.name, charityInfo.address, charityInfo.city, charityInfo.province, charityInfo.postalCode, charityInfo.registration, charityInfo.signature]
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(testData);
    const colWidths = [
      { wch: 18 }, { wch: 20 }, { wch: 12 }, { wch: 25 }, { wch: 15 }, { wch: 12 }, { wch: 12 },
      { wch: 12 }, { wch: 15 }, { wch: 18 }, { wch: 15 }, { wch: 15 }, { wch: 20 }, { wch: 15 },
      { wch: 15 }, { wch: 25 }, { wch: 25 }, { wch: 15 }, { wch: 12 }, { wch: 12 }, { wch: 20 }, { wch: 20 }
    ];
    worksheet['!cols'] = colWidths;

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Complete Receipts');

    XLSX.writeFile(workbook, 'complete-receipts-template.xlsx');
  };

  const importCompleteReceiptsFromExcel = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array', cellDates: true, raw: false });
        
        const worksheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '' });
        
        console.log('Raw Excel Data:', jsonData);

        // Find header row
        const headerRowIndex = jsonData.findIndex(row => 
          row && row.length >= 5 && 
          row[0] && row[0].toString().toLowerCase().includes('receipt') &&
          row[1] && row[1].toString().toLowerCase().includes('donor')
        );
        
        if (headerRowIndex === -1) {
          alert('Could not find receipt data in the uploaded file. Please use the complete template format.');
          return;
        }

        const importedReceipts = [];
        let charityInfo = null;
        
        for (let i = headerRowIndex + 1; i < jsonData.length; i++) {
          const row = jsonData[i];
          
          // Skip empty rows
          if (!row || row.length === 0 || !row[0]) continue;
          
          // Stop if we hit a summary row
          if (row[0] && row[0].toString().toLowerCase().includes('total')) break;

          try {
            // Extract all fields by index
            const fields = {
              receiptNumber: row[0] || '',
              donorName: row[1] || '',
              donorType: row[2] || 'individual',
              donorAddress: row[3] || '',
              donorCity: row[4] || '',
              donorProvince: row[5] || '',
              donorPostalCode: row[6] || '',
              donationDate: row[7] || '',
              donationAmount: row[8] || 0,
              donationType: row[9] || 'cash',
              paymentMethod: row[10] || 'cash',
              advantageProvided: row[11] || 'FALSE',
              advantageDescription: row[12] || '',
              advantageValue: row[13] || 0,
              eligibleAmount: row[14] || 0,
              charityName: row[15] || '',
              charityAddress: row[16] || '',
              charityCity: row[17] || '',
              charityProvince: row[18] || '',
              charityPostalCode: row[19] || '',
              charityRegistrationNumber: row[20] || '',
              authorizedSignature: row[21] || ''
            };

            console.log('Processing row:', fields);

            // Basic validation
            if (!fields.donorName || !fields.receiptNumber) {
              console.warn(`Skipping row ${i + 1}: Missing donor name or receipt number`);
              continue;
            }

            // Parse date - handle multiple formats
            let parsedDonationDate = new Date().toISOString().split('T')[0];
            if (fields.donationDate) {
              try {
                // Try to parse as Date object first
                const date = new Date(fields.donationDate);
                if (!isNaN(date.getTime())) {
                  parsedDonationDate = date.toISOString().split('T')[0];
                } else if (typeof fields.donationDate === 'string') {
                  // Handle "1/15/2024" format manually
                  if (fields.donationDate.includes('/')) {
                    const [month, day, year] = fields.donationDate.split('/');
                    parsedDonationDate = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
                  }
                }
              } catch (dateError) {
                console.warn('Date parsing failed, using current date');
              }
            }

            // Parse boolean values
            const isAdvantageProvided = fields.advantageProvided === 'TRUE' || 
                                      fields.advantageProvided === true || 
                                      fields.advantageProvided === 'true';

            // Store charity info from the first valid row that has charity data
            if (!charityInfo && fields.charityName && fields.charityName.toString().trim()) {
              charityInfo = {
                charityName: fields.charityName.toString().trim(),
                charityAddress: fields.charityAddress.toString().trim(),
                charityCity: fields.charityCity.toString().trim(),
                charityProvince: fields.charityProvince.toString().trim(),
                charityPostalCode: fields.charityPostalCode.toString().trim(),
                charityRegistrationNumber: fields.charityRegistrationNumber.toString().trim(),
                authorizedSignature: fields.authorizedSignature.toString().trim()
              };
              console.log('Extracted charity info:', charityInfo);
            }

            const receiptData = {
              id: Date.now() + i,
              receiptNumber: fields.receiptNumber.toString().trim(),
              issueDate: new Date().toISOString().split('T')[0],
              donationDate: parsedDonationDate,
              donorType: (fields.donorType.toString().toLowerCase() || 'individual').trim(),
              donorName: fields.donorName.toString().trim(),
              donorAddress: fields.donorAddress.toString().trim(),
              donorCity: fields.donorCity.toString().trim(),
              donorProvince: fields.donorProvince.toString().trim(),
              donorPostalCode: fields.donorPostalCode.toString().trim(),
              donationAmount: parseFloat(fields.donationAmount) || 0,
              donationType: (fields.donationType.toString().toLowerCase() || 'cash').trim(),
              paymentMethod: fields.paymentMethod.toString().trim(),
              advantageProvided: isAdvantageProvided,
              advantageDescription: fields.advantageDescription.toString().trim(),
              advantageValue: parseFloat(fields.advantageValue) || 0,
              eligibleAmount: parseFloat(fields.eligibleAmount) || parseFloat(fields.donationAmount) || 0,
              charityName: fields.charityName.toString().trim(),
              charityAddress: fields.charityAddress.toString().trim(),
              charityCity: fields.charityCity.toString().trim(),
              charityProvince: fields.charityProvince.toString().trim(),
              charityPostalCode: fields.charityPostalCode.toString().trim(),
              charityRegistrationNumber: fields.charityRegistrationNumber.toString().trim(),
              authorizedSignature: fields.authorizedSignature.toString().trim()
            };

            console.log('Created receipt:', receiptData);
            importedReceipts.push(receiptData);

          } catch (rowError) {
            console.error(`Error processing row ${i + 1}:`, rowError, 'Row data:', row);
          }
        }

        if (importedReceipts.length > 0) {
          setReceipts(importedReceipts);
          
          // Update current receipt with charity info from the imported data
          if (charityInfo) {
            console.log('Setting charity info in form:', charityInfo);
            setCurrentReceipt(prev => ({
              ...prev,
              ...charityInfo
            }));
            alert(`Successfully imported ${importedReceipts.length} receipt records! Charity information has been updated in the form.`);
          } else {
            alert(`Successfully imported ${importedReceipts.length} receipt records! (No charity information found in import file)`);
          }
        } else {
          alert('No valid receipt records found. Please check your file format and ensure all required fields are filled.');
        }
      } catch (error) {
        console.error('Error importing file:', error);
        alert('Error importing file. Please make sure it\'s a valid Excel file in the complete template format.');
      }
    };
    
    reader.onerror = () => {
      alert('Error reading file. Please try again.');
    };
    
    reader.readAsArrayBuffer(file);
    event.target.value = '';
  };

  const exportToJson = () => {
    const receiptData = {
      items: receipts,
      exportDate: new Date().toISOString(),
      version: '1.0'
    };
    
    const dataStr = JSON.stringify(receiptData, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    
    const link = document.createElement('a');
    link.href = URL.createObjectURL(dataBlob);
    link.download = `receipts-backup-${new Date().getTime()}.json`;
    link.click();
  };

  const importFromJson = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const importedData = JSON.parse(e.target.result);
        
        if (importedData.items && Array.isArray(importedData.items)) {
          setReceipts(importedData.items);
          alert('Receipts successfully restored from backup!');
        } else {
          alert('Invalid backup file format.');
        }
      } catch (error) {
        console.error('Error importing backup:', error);
        alert('Error importing backup file.');
      }
    };
    
    reader.readAsText(file);
    event.target.value = '';
  };

  const resetReceipts = () => {
    if (window.confirm('Are you sure you want to clear all receipts? This action cannot be undone.')) {
      setReceipts([]);
      localStorage.removeItem('donationReceipts');
    }
  };

  const prefillCharityInfo = () => {
    setCurrentReceipt(prev => ({
      ...prev,
      charityName: 'Community Hope Foundation',
      charityAddress: '123 Charity Lane',
      charityCity: 'Toronto',
      charityProvince: 'ON',
      charityPostalCode: 'M5V 1A1',
      charityRegistrationNumber: '123456789RR0001',
      authorizedSignature: 'Jane Smith'
    }));
    alert('Charity information pre-filled! You can now create receipts.');
  };

  return (
    <div className="page">
      <div className="page-header">
        <h1>Donation Receipt Generator</h1>
        <p className="subtitle">Create CRA-compliant donation receipts for Canadian tax purposes</p>
      </div>
      
      <div className="page-content">
        <div className="budget-controls">
          <button onClick={saveReceipt} className="card-btn card-btn-primary">
            💾 Save Receipt
          </button>
          <button onClick={resetReceipts} className="card-btn card-btn-secondary">
            Clear All Receipts
          </button>
          
          <div className="import-export-controls">
            <button onClick={downloadCompleteTemplate} className="card-btn card-btn-secondary">
              📋 Complete Template
            </button>

            <button onClick={prefillCharityInfo} className="card-btn card-btn-secondary">
              🏢 Pre-fill Charity Info
            </button>
            
            <label htmlFor="excel-import" className="card-btn card-btn-secondary">
              📂 Import Excel
            </label>
            <input
              id="excel-import"
              type="file"
              accept=".xlsx,.xls"
              onChange={importCompleteReceiptsFromExcel}
              style={{ display: 'none' }}
            />
            
            <label htmlFor="json-import" className="card-btn card-btn-secondary">
              📂 Import Backup
            </label>
            <input
              id="json-import"
              type="file"
              accept=".json"
              onChange={importFromJson}
              style={{ display: 'none' }}
            />
            
            <button onClick={exportToJson} className="card-btn card-btn-secondary">
              💾 Backup to JSON
            </button>
            
            <button onClick={exportReceiptsAsExcel} className="card-btn card-btn-secondary">
              📊 Export to Excel
            </button>

            <button onClick={() => generatePDF()} className="card-btn card-btn-primary">
              📄 Generate PDF
            </button>

            <button onClick={() => generatePrintableHTML()} className="card-btn card-btn-secondary">
              🖨️ Printable HTML
            </button>
          </div>
        </div>

        {/* Receipt Form */}
        <div className="budget-items">
          <div className="budget-item card">
            <div className="budget-item-header">
              <h4>Receipt Information</h4>
            </div>
            
            <div className="budget-item-fields">
              <div className="form-row">
                <div className="form-group">
                  <label>Receipt Number *</label>
                  <input 
                    type="text"
                    value={currentReceipt.receiptNumber}
                    onChange={(e) => updateCurrentReceipt('receiptNumber', e.target.value)}
                    placeholder="Auto-generated when donor name is entered"
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Issue Date *</label>
                  <input 
                    type="date"
                    value={currentReceipt.issueDate}
                    onChange={(e) => updateCurrentReceipt('issueDate', e.target.value)}
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Donation Date *</label>
                  <input 
                    type="date"
                    value={currentReceipt.donationDate}
                    onChange={(e) => updateCurrentReceipt('donationDate', e.target.value)}
                    required
                  />
                </div>
              </div>

              <h5>Donor Information</h5>
              <div className="form-row">
                <div className="form-group">
                  <label>Donor Name *</label>
                  <input 
                    type="text"
                    value={currentReceipt.donorName}
                    onChange={(e) => updateCurrentReceipt('donorName', e.target.value)}
                    placeholder="Full legal name"
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Donor Type</label>
                  <select 
                    value={currentReceipt.donorType}
                    onChange={(e) => updateCurrentReceipt('donorType', e.target.value)}
                  >
                    <option value="individual">Individual</option>
                    <option value="corporation">Corporation</option>
                    <option value="foundation">Foundation</option>
                  </select>
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Address *</label>
                  <input 
                    type="text"
                    value={currentReceipt.donorAddress}
                    onChange={(e) => updateCurrentReceipt('donorAddress', e.target.value)}
                    placeholder="Street address"
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>City *</label>
                  <input 
                    type="text"
                    value={currentReceipt.donorCity}
                    onChange={(e) => updateCurrentReceipt('donorCity', e.target.value)}
                    placeholder="City"
                    required
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Province *</label>
                  <select 
                    value={currentReceipt.donorProvince}
                    onChange={(e) => updateCurrentReceipt('donorProvince', e.target.value)}
                    required
                  >
                    <option value="">Select Province</option>
                    {provinces.map(province => (
                      <option key={province} value={province}>{province}</option>
                    ))}
                  </select>
                </div>
                
                <div className="form-group">
                  <label>Postal Code *</label>
                  <input 
                    type="text"
                    value={currentReceipt.donorPostalCode}
                    onChange={(e) => updateCurrentReceipt('donorPostalCode', e.target.value)}
                    placeholder="A1A 1A1"
                    required
                  />
                </div>
              </div>

              <h5>Donation Details</h5>
              <div className="form-row">
                <div className="form-group">
                  <label>Donation Amount ($) *</label>
                  <input 
                    type="number"
                    value={currentReceipt.donationAmount}
                    onChange={(e) => updateCurrentReceipt('donationAmount', e.target.value)}
                    step="0.01"
                    min="0"
                    placeholder="0.00"
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Donation Type</label>
                  <select 
                    value={currentReceipt.donationType}
                    onChange={(e) => updateCurrentReceipt('donationType', e.target.value)}
                  >
                    {donationTypes.map(type => (
                      <option key={type} value={type}>{type.charAt(0).toUpperCase() + type.slice(1)}</option>
                    ))}
                  </select>
                </div>
                
                <div className="form-group">
                  <label>Payment Method</label>
                  <input 
                    type="text"
                    value={currentReceipt.paymentMethod}
                    onChange={(e) => updateCurrentReceipt('paymentMethod', e.target.value)}
                    placeholder="Cash, cheque, credit card, etc."
                  />
                </div>
              </div>

              <h5>Advantage Information (if applicable)</h5>
              <div className="form-row">
                <div className="form-group">
                  <label>
                    <input 
                      type="checkbox"
                      checked={currentReceipt.advantageProvided}
                      onChange={(e) => updateCurrentReceipt('advantageProvided', e.target.checked)}
                    />
                    Advantage Provided to Donor?
                  </label>
                </div>
              </div>

              {currentReceipt.advantageProvided && (
                <div className="form-row">
                  <div className="form-group">
                    <label>Advantage Description</label>
                    <input 
                      type="text"
                      value={currentReceipt.advantageDescription}
                      onChange={(e) => updateCurrentReceipt('advantageDescription', e.target.value)}
                      placeholder="Description of goods/services provided"
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Value of Advantage ($)</label>
                    <input 
                      type="number"
                      value={currentReceipt.advantageValue}
                      onChange={(e) => updateCurrentReceipt('advantageValue', e.target.value)}
                      step="0.01"
                      min="0"
                      placeholder="0.00"
                    />
                  </div>
                </div>
              )}

              <div className="form-row">
                <div className="form-group">
                  <label>Eligible Amount</label>
                  <div className="total-cost" style={{fontSize: '1.2em', fontWeight: 'bold'}}>
                    ${parseFloat(currentReceipt.eligibleAmount).toFixed(2)}
                  </div>
                  <small>This is the amount the donor can claim on their taxes</small>
                </div>
              </div>

              <h5>Charity Information</h5>
              <div className="form-row">
                <div className="form-group">
                  <label>Charity Name</label>
                  <input 
                    type="text"
                    value={currentReceipt.charityName}
                    onChange={(e) => updateCurrentReceipt('charityName', e.target.value)}
                    placeholder="Your charity's legal name"
                  />
                </div>
                
                <div className="form-group">
                  <label>Registration Number</label>
                  <input 
                    type="text"
                    value={currentReceipt.charityRegistrationNumber}
                    onChange={(e) => updateCurrentReceipt('charityRegistrationNumber', e.target.value)}
                    placeholder="CRA registration number"
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Charity Address</label>
                  <input 
                    type="text"
                    value={currentReceipt.charityAddress}
                    onChange={(e) => updateCurrentReceipt('charityAddress', e.target.value)}
                    placeholder="Charity street address"
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>City</label>
                  <input 
                    type="text"
                    value={currentReceipt.charityCity}
                    onChange={(e) => updateCurrentReceipt('charityCity', e.target.value)}
                    placeholder="City"
                  />
                </div>
                
                <div className="form-group">
                  <label>Province</label>
                  <select 
                    value={currentReceipt.charityProvince}
                    onChange={(e) => updateCurrentReceipt('charityProvince', e.target.value)}
                  >
                    <option value="">Select Province</option>
                    {provinces.map(province => (
                      <option key={province} value={province}>{province}</option>
                    ))}
                  </select>
                </div>
                
                <div className="form-group">
                  <label>Postal Code</label>
                  <input 
                    type="text"
                    value={currentReceipt.charityPostalCode}
                    onChange={(e) => updateCurrentReceipt('charityPostalCode', e.target.value)}
                    placeholder="A1A 1A1"
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Authorized Signature</label>
                  <input 
                    type="text"
                    value={currentReceipt.authorizedSignature}
                    onChange={(e) => updateCurrentReceipt('authorizedSignature', e.target.value)}
                    placeholder="Name of authorized signatory"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Saved Receipts List */}
        {receipts.length > 0 && (
          <div className="budget-summary card">
            <h3>Saved Receipts ({receipts.length})</h3>
            <div className="receipts-list">
              {receipts.map((receipt, index) => (
                <div key={receipt.id} className="receipt-item">
                  <div className="receipt-info">
                    <strong>{receipt.receiptNumber}</strong>
                    <span>{receipt.donorName}</span>
                    <span>${parseFloat(receipt.eligibleAmount).toFixed(2)}</span>
                    <span>{receipt.donationDate}</span>
                  </div>
                  <div className="receipt-actions">
                    <button 
                      onClick={() => loadReceipt(receipt)}
                      className="card-btn card-btn-secondary"
                    >
                      Edit
                    </button>
                    <button 
                      onClick={() => generatePDF(receipt)}
                      className="card-btn card-btn-secondary"
                    >
                      PDF
                    </button>
                    <button 
                      onClick={() => generatePrintableHTML(receipt)}
                      className="card-btn card-btn-secondary"
                    >
                      Print
                    </button>
                    <button 
                      onClick={() => deleteReceipt(receipt.id)}
                      className="remove-btn"
                    >
                      ×
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {receipts.length === 0 && (
          <div className="empty-state card">
            <h3>Create Your First Donation Receipt</h3>
            <p>Fill out the form above to generate CRA-compliant donation receipts for your donors.</p>
            <ul className="budget-tips">
              <li>💡 <strong>CRA Compliant:</strong> Includes all required fields for official tax receipts</li>
              <li>💡 <strong>Auto-Calculation:</strong> Automatically calculates eligible amount when advantages are provided</li>
              <li>💡 <strong>Multiple Formats:</strong> Generate PDFs or printable HTML receipts</li>
              <li>💡 <strong>Data Management:</strong> Save, export, and import receipt data</li>
              <li>💡 <strong>Auto-Save:</strong> All receipts are automatically saved to your browser</li>
              <li>💡 <strong>Receipt Numbering:</strong> Automatic receipt number generation</li>
              <li>💡 <strong>Charity Info:</strong> Use "Pre-fill Charity Info" or import from Excel template</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default DonationReceiptGenerator;