import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import './Pages.css';

const InKindDonationTracker = () => {
  const [donations, setDonations] = useState([]);
  const [totalValue, setTotalValue] = useState(0);

  // Updated donation types to align with common CRA categories
  const donationTypes = [
    'Goods/Equipment',
    'Publicly Traded Securities',
    'Cultural Property',
    'Ecological Gifts',
    'Real Property',
    'Other'
  ];

  // Load from localStorage on component mount
  React.useEffect(() => {
    const savedDonations = localStorage.getItem('inKindDonations');
    if (savedDonations) {
      try {
        const parsedDonations = JSON.parse(savedDonations);
        setDonations(parsedDonations.items || []);
        setTotalValue(parsedDonations.totalValue || 0);
      } catch (error) {
        console.error('Error loading saved donations:', error);
      }
    }
  }, []);

  // Save to localStorage whenever donations change
  React.useEffect(() => {
    const donationData = {
      items: donations,
      totalValue: totalValue,
      lastUpdated: new Date().toISOString()
    };
    localStorage.setItem('inKindDonations', JSON.stringify(donationData));
  }, [donations, totalValue]);

  const addDonation = () => {
    const newDonation = {
      id: Date.now(),
      donorName: '',
      donorAddress: '', // Required by CRA for receipts 
      donationType: '',
      description: '',
      dateReceived: new Date().toISOString().split('T')[0],
      fairMarketValue: 0,
      advantageReceived: '', // New field for split receipting
      advantageValue: 0, // Value of any benefit donor received
      eligibleAmount: 0, // FMV minus advantage value 
      quantity: 1,
      appraiserName: '', // Required for items over $1,000 
      appraiserAddress: ''
    };
    setDonations([...donations, newDonation]);
  };

  const updateDonation = (id, field, value) => {
    const updatedDonations = donations.map(donation => {
      if (donation.id === id) {
        const updatedDonation = { ...donation, [field]: value };
        
        // Recalculate eligible amount if FMV or advantage value changes
        if (field === 'fairMarketValue' || field === 'advantageValue') {
          // Calculate eligible amount per CRA rules: FMV minus advantage value 
          const advantageVal = parseFloat(updatedDonation.advantageValue) || 0;
          const fmv = parseFloat(updatedDonation.fairMarketValue) || 0;
          
          // Check if advantage exceeds 80% of donation value 
          if (advantageVal > 0.8 * fmv) {
            // If advantage > 80%, no receipt can be issued 
            updatedDonation.eligibleAmount = 0;
          } else {
            // Check for de minimis rule (advantage <= $75 and <= 10% of donation) 
            if (advantageVal <= 75 && advantageVal <= 0.1 * fmv) {
              updatedDonation.eligibleAmount = fmv;
            } else {
              updatedDonation.eligibleAmount = fmv - advantageVal;
            }
          }
        }
        
        return updatedDonation;
      }
      return donation;
    });
    
    setDonations(updatedDonations);
    calculateTotalValue(updatedDonations);
  };

  const removeDonation = (id) => {
    const filteredDonations = donations.filter(donation => donation.id !== id);
    setDonations(filteredDonations);
    calculateTotalValue(filteredDonations);
  };

  const calculateTotalValue = (items) => {
    const newTotal = items.reduce((sum, item) => sum + (item.eligibleAmount || 0), 0);
    setTotalValue(newTotal);
  };

  const resetDonations = () => {
    if (window.confirm('Are you sure you want to clear all donation records? This action cannot be undone.')) {
      setDonations([]);
      setTotalValue(0);
      localStorage.removeItem('inKindDonations');
    }
  };

  const importDonationsFromExcel = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        
        const worksheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });
        
        // Find header row
        const headerRowIndex = jsonData.findIndex(row => 
          row && row.length >= 5 && 
          typeof row[0] === 'string' && row[0].toLowerCase().includes('donor')
        );
        
        if (headerRowIndex === -1) {
          alert('Could not find donation data in the uploaded file. Please use the template format.');
          return;
        }

        const importedDonations = [];
        const headers = jsonData[headerRowIndex];
        
        for (let i = headerRowIndex + 1; i < jsonData.length; i++) {
          const row = jsonData[i];
          
          // Skip empty rows or summary rows
          if (!row || row.length === 0 || !row[0]) continue;
          
          // Stop if we hit a total row
          if (typeof row[0] === 'string' && row[0].toLowerCase().includes('total')) break;

          try {
            const [
              donorName = '',
              donorAddress = '',
              donationType = '',
              description = '',
              dateReceived = '',
              fairMarketValue = 0,
              advantageReceived = '',
              advantageValue = 0,
              eligibleAmount = 0
            ] = row;

            // Basic validation
            if (!donorName || !description) {
              console.warn(`Skipping row ${i + 1}: Missing required fields`);
              continue;
            }

            // Parse dates - handle various formats
            let parsedDate = dateReceived;
            if (dateReceived && typeof dateReceived === 'number') {
              // Excel serial date
              parsedDate = XLSX.SSF.format('yyyy-mm-dd', dateReceived);
            } else if (dateReceived && typeof dateReceived === 'string') {
              // Keep as is if it's already a string
              parsedDate = dateReceived;
            } else {
              parsedDate = new Date().toISOString().split('T')[0];
            }

            importedDonations.push({
              id: Date.now() + i,
              donorName: donorName.toString(),
              donorAddress: donorAddress.toString(),
              donationType: donationType.toString(),
              description: description.toString(),
              dateReceived: parsedDate,
              fairMarketValue: parseFloat(fairMarketValue) || 0,
              advantageReceived: advantageReceived.toString(),
              advantageValue: parseFloat(advantageValue) || 0,
              eligibleAmount: parseFloat(eligibleAmount) || 0,
              quantity: 1,
              appraiserName: parseFloat(fairMarketValue) > 1000 ? 'To be completed' : '',
              appraiserAddress: parseFloat(fairMarketValue) > 1000 ? 'To be completed' : ''
            });

          } catch (rowError) {
            console.warn(`Error processing row ${i + 1}:`, rowError);
          }
        }

        if (importedDonations.length > 0) {
          setDonations(importedDonations);
          calculateTotalValue(importedDonations);
          alert(`Successfully imported ${importedDonations.length} donation records!`);
        } else {
          alert('No valid donation records found. Please check your file format.');
        }
      } catch (error) {
        console.error('Error importing file:', error);
        alert('Error importing file. Please make sure it\'s a valid Excel file in the correct format.');
      }
    };
    
    reader.onerror = () => {
      alert('Error reading file. Please try again.');
    };
    
    reader.readAsArrayBuffer(file);
    event.target.value = '';
  };

  const exportToJson = () => {
    const donationData = {
      items: donations,
      totalValue: totalValue,
      exportDate: new Date().toISOString(),
      version: '1.0'
    };
    
    const dataStr = JSON.stringify(donationData, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    
    const link = document.createElement('a');
    link.href = URL.createObjectURL(dataBlob);
    link.download = `donations-backup-${new Date().getTime()}.json`;
    link.click();
  };

  const importFromJson = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const importedData = JSON.parse(e.target.result);
        
        if (importedData.items && Array.isArray(importedData.items)) {
          setDonations(importedData.items);
          setTotalValue(importedData.totalValue || 0);
          alert('Donations successfully restored from backup!');
        } else {
          alert('Invalid backup file format.');
        }
      } catch (error) {
        console.error('Error importing backup:', error);
        alert('Error importing backup file. Please make sure it\'s a valid backup from this app.');
      }
    };
    
    reader.readAsText(file);
    event.target.value = '';
  };

  // NEW: Generate CRA-compliant official donation receipt
  const generateCRAReceipt = (donation) => {
    const receiptData = [
      ['OFFICIAL DONATION RECEIPT FOR INCOME TAX PURPOSES'],
      [''],
      ['Charity Information:'],
      [`Legal Name: [Your Charity's Legal Name]`],
      [`Address: [Your Charity's Full Address]`],
      [`Registration Number: [Your CRA Registration Number]`],
      [''],
      ['Donor Information:'],
      [`Name: ${donation.donorName}`],
      [`Address: ${donation.donorAddress}`],
      [''],
      ['Donation Details:'],
      [`Date of Donation: ${donation.dateReceived}`],
      [`Description: ${donation.description}`],
      [`Donation Type: ${donation.donationType}`],
      [`Fair Market Value: $${donation.fairMarketValue.toFixed(2)}`],
      ...(donation.advantageValue > 0 ? [
        [`Advantage Received: ${donation.advantageReceived}`],
        [`Value of Advantage: $${donation.advantageValue.toFixed(2)}`]
      ] : []),
      [`Eligible Amount: $${donation.eligibleAmount.toFixed(2)}`],
      ...(donation.appraiserName ? [
        [''],
        ['Appraisal Information:'],
        [`Appraiser: ${donation.appraiserName}`],
        [`Appraiser Address: ${donation.appraiserAddress}`]
      ] : []),
      [''],
      ['Authorized Signature: ________________________'],
      [`Date Issued: ${new Date().toLocaleDateString()}`],
      [`Receipt Number: ${donation.id}`]
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(receiptData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Official Receipt');

    const fileName = `cra-receipt-${donation.id}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  const downloadDonationsAsExcel = () => {
    const excelData = [
      ['In-Kind Donation Tracker - Canada', '', '', '', '', '', '', '', ''],
      ['Generated on:', new Date().toLocaleDateString(), '', '', '', '', '', '', ''],
      ['', '', '', '', '', '', '', '', ''],
      ['Donor Name', 'Donor Address', 'Donation Type', 'Description', 'Date Received', 'Fair Market Value ($)', 'Advantage Description', 'Advantage Value ($)', 'Eligible Amount ($)'],
      ...donations.map(donation => [
        donation.donorName,
        donation.donorAddress,
        donation.donationType,
        donation.description,
        donation.dateReceived,
        donation.fairMarketValue,
        donation.advantageReceived,
        donation.advantageValue,
        donation.eligibleAmount
      ]),
      ['', '', '', '', '', '', '', '', ''],
      ['', '', '', '', '', '', '', 'TOTAL ELIGIBLE AMOUNT:', `$${totalValue.toFixed(2)}`]
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(excelData);
    const colWidths = [
      { wch: 25 }, { wch: 30 }, { wch: 20 }, { wch: 40 }, 
      { wch: 15 }, { wch: 18 }, { wch: 25 }, { wch: 18 }, { wch: 18 }
    ];
    worksheet['!cols'] = colWidths;

    if (!worksheet['!merges']) worksheet['!merges'] = [];
    worksheet['!merges'].push({ s: { r: 0, c: 0 }, e: { r: 0, c: 8 } });

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'In-Kind Donations');

    const fileName = `in-kind-donations-${new Date().getTime()}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  // NEW FUNCTION: Download test template
  const downloadTestTemplate = () => {
    const testData = [
      ['Donor Name', 'Donor Address', 'Donation Type', 'Description', 'Date Received', 'Fair Market Value ($)', 'Advantage Description', 'Advantage Value ($)', 'Eligible Amount ($)'],
      ['John Smith', '123 Maple St, Toronto, ON M5V 2T1', 'Goods/Equipment', '5 office chairs for staff use', '2024-01-15', 750, '', 0, 750],
      ['Sarah Chen', '456 Oak Avenue, Vancouver, BC V6B 2T2', 'Professional Services', 'Marketing consultation - 10 hours', '2024-01-20', 1500, 'Complimentary lunch', 25, 1475],
      ['GreenTech Inc.', '789 Corporate Blvd, Calgary, AB T2P 3G7', 'Equipment', 'Laptop computers (3 units) for program delivery', '2024-02-01', 4200, 'Company recognition in newsletter', 0, 4200],
      ['Maria Rodriguez', '101 Pine Road, Montreal, QC H3A 1T1', 'Other', 'Art supplies for youth program', '2024-02-10', 300, '', 0, 300],
      ['David Kim', '202 Birch Lane, Ottawa, ON K1P 5G7', 'Goods/Equipment', 'Professional camera equipment', '2024-02-15', 2500, 'Photography workshop attendance', 150, 2350]
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(testData);
    const colWidths = [
      { wch: 20 }, { wch: 30 }, { wch: 18 }, { wch: 35 }, 
      { wch: 12 }, { wch: 18 }, { wch: 25 }, { wch: 18 }, { wch: 18 }
    ];
    worksheet['!cols'] = colWidths;

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Test Donations');

    XLSX.writeFile(workbook, 'test-donations-template.xlsx');
  };

  return (
    <div className="page">
      <div className="page-header">
        <h1>In-Kind Donation Tracker - Canada</h1>
        <p className="subtitle">CRA-compliant tracking for non-cash contributions and official donation receipts</p>
      </div>
      
      <div className="page-content">
        <div className="budget-controls">
          <button onClick={addDonation} className="card-btn">
            + Add Donation
          </button>
          <button onClick={resetDonations} className="card-btn card-btn-secondary">
            Clear All
          </button>
          
          <div className="import-export-controls">
            <button onClick={downloadTestTemplate} className="card-btn card-btn-secondary">
              📋 Test Template
            </button>
            
            <label htmlFor="excel-import" className="card-btn card-btn-secondary">
              📂 Import Excel
            </label>
            <input
              id="excel-import"
              type="file"
              accept=".xlsx,.xls"
              onChange={importDonationsFromExcel}
              style={{ display: 'none' }}
            />
            
            <label htmlFor="json-import" className="card-btn card-btn-secondary">
              📂 Import Backup
            </label>
            <input
              id="json-import"
              type="file"
              accept=".json"
              onChange={importFromJson}
              style={{ display: 'none' }}
            />
            
            <button onClick={exportToJson} className="card-btn card-btn-secondary">
              💾 Backup to JSON
            </button>
            
            <button onClick={downloadDonationsAsExcel} className="card-btn card-btn-secondary">
              📊 Export for CRA
            </button>
          </div>
        </div>

        <div className="budget-items">
          {donations.map((donation, index) => (
            <div key={donation.id} className="budget-item card">
              <div className="budget-item-header">
                <h4>Donation #{index + 1}</h4>
                <div>
                  <button 
                    onClick={() => generateCRAReceipt(donation)}
                    className="card-btn card-btn-primary"
                    style={{marginRight: '10px'}}
                    disabled={donation.eligibleAmount <= 0}
                  >
                    🧾 Generate CRA Receipt
                  </button>
                  <button 
                    onClick={() => removeDonation(donation.id)}
                    className="remove-btn"
                  >
                    ×
                  </button>
                </div>
              </div>
              
              <div className="budget-item-fields">
                <div className="form-group">
                  <label>Donor Full Name *</label>
                  <input 
                    type="text"
                    value={donation.donorName}
                    onChange={(e) => updateDonation(donation.id, 'donorName', e.target.value)}
                    placeholder="Legal name as it appears on tax return"
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Donor Full Address *</label>
                  <textarea 
                    value={donation.donorAddress}
                    onChange={(e) => updateDonation(donation.id, 'donorAddress', e.target.value)}
                    placeholder="Complete mailing address for tax receipt"
                    rows="2"
                    required
                  />
                </div>
                
                <div className="form-group">
                  <label>Donation Type</label>
                  <select 
                    value={donation.donationType}
                    onChange={(e) => updateDonation(donation.id, 'donationType', e.target.value)}
                  >
                    <option value="">Select donation type</option>
                    {donationTypes.map(type => (
                      <option key={type} value={type}>{type}</option>
                    ))}
                  </select>
                </div>
                
                <div className="form-group">
                  <label>Description of Property *</label>
                  <textarea 
                    value={donation.description}
                    onChange={(e) => updateDonation(donation.id, 'description', e.target.value)}
                    placeholder="Detailed description of donated property..."
                    rows="2"
                    required
                  />
                </div>
                
                <div className="budget-numbers">
                  <div className="form-group">
                    <label>Date Received *</label>
                    <input 
                      type="date"
                      value={donation.dateReceived}
                      onChange={(e) => updateDonation(donation.id, 'dateReceived', e.target.value)}
                      required
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Fair Market Value ($) *</label>
                    <input 
                      type="number"
                      value={donation.fairMarketValue}
                      onChange={(e) => updateDonation(donation.id, 'fairMarketValue', parseFloat(e.target.value) || 0)}
                      step="0.01"
                      min="0"
                      placeholder="0.00"
                      required
                    />
                  </div>

                  {/* New Advantage Fields */}
                  <div className="form-group">
                    <label>Advantage Received</label>
                    <input 
                      type="text"
                      value={donation.advantageReceived}
                      onChange={(e) => updateDonation(donation.id, 'advantageReceived', e.target.value)}
                      placeholder="Description of any benefit to donor"
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Value of Advantage ($)</label>
                    <input 
                      type="number"
                      value={donation.advantageValue}
                      onChange={(e) => updateDonation(donation.id, 'advantageValue', parseFloat(e.target.value) || 0)}
                      step="0.01"
                      min="0"
                      placeholder="0.00"
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Eligible Amount</label>
                    <div className="total-cost">
                      ${donation.eligibleAmount.toFixed(2)}
                      {donation.advantageValue > 0.8 * donation.fairMarketValue && (
                        <div style={{color: 'red', fontSize: '0.8em'}}>
                          No receipt allowed (advantage {`>`} 80%)
                        </div>
                      )}
                    </div>
                  </div>
                </div>

                {/* Appraiser fields for high-value items */}
                {donation.fairMarketValue > 1000 && (
                  <div className="appraiser-section">
                    <h5>Appraisal Information (Recommended for items over $1,000)</h5>
                    <div className="form-group">
                      <label>Appraiser Name</label>
                      <input 
                        type="text"
                        value={donation.appraiserName}
                        onChange={(e) => updateDonation(donation.id, 'appraiserName', e.target.value)}
                        placeholder="Name of qualified appraiser"
                      />
                    </div>
                    <div className="form-group">
                      <label>Appraiser Address</label>
                      <textarea 
                        value={donation.appraiserAddress}
                        onChange={(e) => updateDonation(donation.id, 'appraiserAddress', e.target.value)}
                        placeholder="Appraiser's business address"
                        rows="2"
                      />
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>

        {donations.length > 0 && (
          <div className="budget-summary card">
            <h3>Donation Summary</h3>
            <div className="total-amount">
              <strong>Total Eligible Amount for Tax Receipts: ${totalValue.toFixed(2)}</strong>
            </div>
            <div className="download-info">
              <p><strong>{donations.length}</strong> donation records tracked</p>
              <p>Use "Generate CRA Receipt" for individual official donation receipts or "Export for CRA" for comprehensive reporting.</p>
            </div>
          </div>
        )}

        {donations.length === 0 && (
          <div className="empty-state card">
            <h3>Start Tracking In-Kind Donations</h3>
            <p>Click "Add Donation" to begin recording non-cash contributions in compliance with CRA requirements.</p>
            <ul className="budget-tips">
              <li>💡 <strong>Legal Requirement:</strong> Include donor's full name and address on all official receipts </li>
              <li>💡 <strong>Valuation:</strong> Use Fair Market Value - price in open market between willing parties </li>
              <li>💡 <strong>Split Receipting:</strong> Subtract value of any advantages provided to donor </li>
              <li>💡 <strong>Professional Appraisal:</strong> Recommended for items over $1,000 </li>
              <li>💡 <strong>No Services:</strong> Cannot issue receipts for donated services or time </li>
              <li>💡 <strong>Test First:</strong> Use "Test Template" to try the import functionality</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default InKindDonationTracker;