import React from 'react';
import './Pages.css';

const Home = () => {
  return (
    <div className="page">
      <div className="page-header">
        <h1>Welcome to Michael's CivicTech Sandbox</h1>
        <p className="subtitle">Exploring technology solutions for civic engagement and social impact</p>
      </div>
      
      <div className="page-content">
        <div className="card-grid">
          <div className="card">
            <h3>🚀 About This Space</h3>
            <p>This is my playground for experimenting with civic technology tools, prototypes, and ideas that can make a positive impact in our communities.</p>
          </div>
          
          <div className="card">
            <h3>🎯 Current Focus</h3>
            <p>Developing accessible tools for grant management, community engagement, and data visualization for public good projects.</p>
          </div>
          
          <div className="card">
            <h3>🔧 Technologies</h3>
            <p>React, Node.js, Python, GIS mapping, data analytics, and user-centered design principles.</p>
          </div>
          
          <div className="card">
            <h3>🤝 Collaboration</h3>
            <p>Open to partnerships with nonprofits, government agencies, and fellow civic tech enthusiasts.</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;