import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Home from './pages/Home';
import GrantToolbox from './pages/GrantToolbox';
import CalgaryGrantDirectory from './pages/CalgaryGrantDirectory';
import GrantApplicationNotes from './pages/GrantApplicationNotes';
import BudgetTemplateGenerator from './pages/BudgetTemplateGenerator';
import GrantApplicationAIBuilder from './pages/GrantApplicationAIBuilder';
import './App.css';
import MissionVision from './pages/MissionVision';
import PhilosophyApproach from './pages/PhilosophyApproach';
import StatementOfNeed from './pages/StatementOfNeed';
import ProgramDescription from './pages/ProgramDescription';
import Accountability from './pages/Accountability';
import Sustainability from './pages/Sustainability';
import PartnershipsVolunteers from './pages/PartnershipsVolunteers';
import GovernanceLeadership from './pages/GovernanceLeadership';
import BookkeeperToolbox from './pages/BookkeeperToolbox';
import TransactionImporter from './pages/TransactionImporter';
import GrantFundTracker from './pages/GrantFundTracker';
import CheckVoucherGenerator from './pages/CheckVoucherGenerator';
import ProgramIncomeStatement from './pages/ProgramIncomeStatement';
import CashFlowSnapshot from './pages/CashFlowSnapshot';
import BudgetVsActualDashboard from './pages/BudgetVsActualDashboard';
import InKindDonationTracker from './pages/InKindDonationTracker';
import DonationReceiptGenerator from './pages/DonationReceiptGenerator';
import FundraisingEventPnLCalculator from './pages/FundraisingEventPnLCalculator';
import PettyCashManager from './pages/PettyCashManager';
import AgingSummaries from './pages/AgingSummaries';
import DatathonProjects from './pages/DatathonProjects';
import Datathon2026SecondarySuites from './pages/Datathon2026SecondarySuites';
function App() {
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  const [sidebarOpen, setSidebarOpen] = useState(!isMobile);

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 768;
      setIsMobile(mobile);
      setSidebarOpen(!mobile);
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  return (
    <Router>
      <div className="app">
        <Sidebar 
          isOpen={sidebarOpen} 
          isMobile={isMobile}
          onToggle={toggleSidebar}
          onClose={() => setSidebarOpen(false)}
        />
        
        <main className={`main-content ${sidebarOpen ? 'sidebar-open' : ''}`}>
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/grant-toolbox" element={<GrantToolbox />} />
            <Route path="/grant-application-notes" element={<GrantApplicationNotes />} />
            <Route path="/budget-template-generator" element = {<BudgetTemplateGenerator/>} />
            <Route path="/calgary-grant-directory" element={<CalgaryGrantDirectory />} /> 
            <Route path="/grant-application-ai-builder" element={<GrantApplicationAIBuilder/>} />
            <Route path="/mission-vision" element={<MissionVision/>} />
            <Route path="/philosophy-approach" element={<PhilosophyApproach/>} />
            <Route path="/statement-of-need" element={<StatementOfNeed/>} />
            <Route path="/program-descriptions" element={<ProgramDescription/>} />
            <Route path="/accountability" element={<Accountability/>} />
            <Route path="/sustainability" element={<Sustainability/>} />
            <Route path="/partnerships-volunteers" element={<PartnershipsVolunteers/>} />
            <Route path="/governance-leadership" element={<GovernanceLeadership/>} />
            <Route path="/bookkeeper-toolbox" element={<BookkeeperToolbox/>} />
            <Route path="/transaction-importer" element={<TransactionImporter/>} />
            <Route path="/grant-fund-tracker" element={<GrantFundTracker/>} />
            <Route path="/check-generator" element={<CheckVoucherGenerator/>} />
            <Route path="/program-income-statement" element={<ProgramIncomeStatement/>} />
            <Route path="/cash-flow-snapshot" element={<CashFlowSnapshot/>} />
            <Route path="/budget-vs-actual" element={<BudgetVsActualDashboard/>} />
            <Route path="/in-kind-tracker" element={<InKindDonationTracker/>} />
            <Route path="/donation-receipts" element={<DonationReceiptGenerator/>} />
            <Route path="/event-pl-calculator" element={<FundraisingEventPnLCalculator/>} />
            <Route path="/petty-cash-manager" element={<PettyCashManager/>} />
            <Route path="/ap-ar-aging" element={<AgingSummaries/>} />
            <Route path="/datathon-projects" element={<DatathonProjects />} />
            <Route path="/datathon-2026-secondary-suites" element={<Datathon2026SecondarySuites />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default App;