import React, { useState, useEffect } from 'react';
import * as XLSX from 'xlsx';
import './Pages.css';

const BudgetVsActualDashboard = () => {
  const [budgetData, setBudgetData] = useState([]);
  const [actualTransactions, setActualTransactions] = useState([]);
  const [timePeriod, setTimePeriod] = useState('ytd');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Common nonprofit budget categories
  const budgetCategories = [
    'Personnel & Salaries',
    'Equipment & Supplies',
    'Travel & Transportation',
    'Materials & Printing',
    'Facility Costs',
    'Professional Services',
    'Administrative Costs',
    'Program Expenses',
    'Fundraising Costs',
    'Other Expenses'
  ];

  // Load from localStorage on component mount
  useEffect(() => {
    const savedBudget = localStorage.getItem('budgetVsActualBudget');
    const savedTransactions = localStorage.getItem('importedTransactions');
    
    if (savedBudget) {
      try {
        setBudgetData(JSON.parse(savedBudget));
      } catch (error) {
        console.error('Error loading saved budget:', error);
      }
    }

    if (savedTransactions) {
      try {
        setActualTransactions(JSON.parse(savedTransactions));
      } catch (error) {
        console.error('Error loading saved transactions:', error);
      }
    }

    // Set default date range to year-to-date
    const end = new Date();
    const start = new Date();
    start.setMonth(0);
    start.setDate(1);
    
    setStartDate(start.toISOString().split('T')[0]);
    setEndDate(end.toISOString().split('T')[0]);
  }, []);

  // Save to localStorage whenever data changes
  useEffect(() => {
    localStorage.setItem('budgetVsActualBudget', JSON.stringify(budgetData));
  }, [budgetData]);

  // Update date range when time period changes
  useEffect(() => {
    const end = new Date();
    const start = new Date();

    switch (timePeriod) {
      case 'last30':
        start.setDate(start.getDate() - 30);
        break;
      case 'last90':
        start.setDate(start.getDate() - 90);
        break;
      case 'ytd':
        start.setMonth(0);
        start.setDate(1);
        break;
      case 'lastYear':
        start.setFullYear(start.getFullYear() - 1);
        start.setMonth(0);
        start.setDate(1);
        end.setFullYear(end.getFullYear() - 1);
        end.setMonth(11);
        end.setDate(31);
        break;
      default:
        break;
    }

    if (timePeriod !== 'custom') {
      setStartDate(start.toISOString().split('T')[0]);
      setEndDate(end.toISOString().split('T')[0]);
    }
  }, [timePeriod]);

  // Filter transactions by date range
  const getFilteredTransactions = () => {
    if (!startDate || !endDate) return actualTransactions;

    return actualTransactions.filter(transaction => {
      try {
        const transactionDate = new Date(transaction.date);
        const start = new Date(startDate);
        const end = new Date(endDate);
        
        return transactionDate >= start && transactionDate <= end;
      } catch (error) {
        console.error('Error filtering transaction:', transaction, error);
        return false;
      }
    });
  };

  // Calculate actual amounts by category
  const calculateActuals = () => {
    const filteredTransactions = getFilteredTransactions();
    const actuals = {};

    budgetCategories.forEach(category => {
      actuals[category] = 0;
    });

    // Add "Revenue" category for income
    actuals['Revenue'] = 0;

    filteredTransactions.forEach(transaction => {
      const category = transaction.category || 'Other Expenses';
      const amount = Math.abs(transaction.amount);

      if (transaction.type === 'Income' || transaction.amount > 0) {
        actuals['Revenue'] += amount;
      } else {
        if (actuals[category] !== undefined) {
          actuals[category] += amount;
        } else {
          actuals['Other Expenses'] += amount;
        }
      }
    });

    return actuals;
  };

  // Calculate budget vs actual comparison
  const calculateComparison = () => {
    const actuals = calculateActuals();
    const comparison = [];

    // Add revenue comparison
    const revenueBudget = budgetData.find(item => item.category === 'Revenue')?.amount || 0;
    const revenueActual = actuals['Revenue'] || 0;
    const revenueVariance = revenueActual - revenueBudget;
    const revenueVariancePercent = revenueBudget > 0 ? (revenueVariance / revenueBudget) * 100 : 0;

    comparison.push({
      category: 'Revenue',
      budget: revenueBudget,
      actual: revenueActual,
      variance: revenueVariance,
      variancePercent: revenueVariancePercent,
      type: 'revenue'
    });

    // Add expense comparisons
    budgetCategories.forEach(category => {
      const budgetItem = budgetData.find(item => item.category === category);
      const budgetAmount = budgetItem?.amount || 0;
      const actualAmount = actuals[category] || 0;
      const variance = budgetAmount - actualAmount; // Positive = under budget, Negative = over budget
      const variancePercent = budgetAmount > 0 ? (variance / budgetAmount) * 100 : 0;

      comparison.push({
        category,
        budget: budgetAmount,
        actual: actualAmount,
        variance,
        variancePercent,
        type: 'expense'
      });
    });

    return comparison;
  };

  // Add budget item
  const addBudgetItem = () => {
    const newItem = {
      id: Date.now(),
      category: '',
      amount: 0,
      description: ''
    };
    setBudgetData([...budgetData, newItem]);
  };

  // Update budget item
  const updateBudgetItem = (id, field, value) => {
    const updatedBudget = budgetData.map(item => {
      if (item.id === id) {
        return { ...item, [field]: value };
      }
      return item;
    });
    setBudgetData(updatedBudget);
  };

  // Remove budget item
  const removeBudgetItem = (id) => {
    const filteredBudget = budgetData.filter(item => item.id !== id);
    setBudgetData(filteredBudget);
  };

  // Import budget from Excel
  const importBudgetFromExcel = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        const worksheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });
        
        // Find header row and map columns
        const headers = jsonData[0] || [];
        const categoryIndex = headers.findIndex(h => 
          h && h.toString().toLowerCase().includes('category'));
        const amountIndex = headers.findIndex(h => 
          h && h.toString().toLowerCase().includes('amount'));
        const descriptionIndex = headers.findIndex(h => 
          h && h.toString().toLowerCase().includes('description'));

        if (categoryIndex === -1 || amountIndex === -1) {
          alert('Could not find required columns (Category, Amount). Please check your Excel file format.');
          return;
        }

        // Process budget items from Excel data
        const importedBudget = [];
        for (let i = 1; i < jsonData.length; i++) {
          const row = jsonData[i];
          if (!row || row.length === 0) continue;

          const category = row[categoryIndex] || '';
          const amount = parseFloat(row[amountIndex]) || 0;
          const description = row[descriptionIndex] || '';

          // Skip if no category or amount
          if (!category || amount === 0) continue;

          importedBudget.push({
            id: Date.now() + i,
            category: category.toString(),
            amount: Math.abs(amount),
            description: description.toString()
          });
        }

        if (importedBudget.length > 0) {
          setBudgetData(importedBudget);
          alert(`Successfully imported ${importedBudget.length} budget items!`);
        } else {
          alert('No valid budget items found in the Excel file.');
        }
      } catch (error) {
        console.error('Error importing budget file:', error);
        alert('Error importing budget file. Please make sure it\'s a valid Excel file with the correct columns.');
      }
    };
    
    reader.onerror = () => {
      alert('Error reading file. Please try again.');
    };
    
    reader.readAsArrayBuffer(file);
    event.target.value = '';
  };

  // UPDATED: Import transactions from Excel (replaced JSON import)
  const importTransactionsFromExcel = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        const worksheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });
        
        // Find header row and map columns
        const headers = jsonData[0] || [];
        const dateIndex = headers.findIndex(h => 
          h && h.toString().toLowerCase().includes('date'));
        const descriptionIndex = headers.findIndex(h => 
          h && h.toString().toLowerCase().includes('description'));
        const amountIndex = headers.findIndex(h => 
          h && (h.toString().toLowerCase().includes('amount') || 
                h.toString().toLowerCase().includes('debit') || 
                h.toString().toLowerCase().includes('credit')));
        const categoryIndex = headers.findIndex(h => 
          h && h.toString().toLowerCase().includes('category'));
        const typeIndex = headers.findIndex(h => 
          h && h.toString().toLowerCase().includes('type'));

        if (dateIndex === -1 || descriptionIndex === -1 || amountIndex === -1) {
          alert('Could not find required columns (Date, Description, Amount). Please check your Excel file format.');
          return;
        }

        // Process transactions from Excel data
        const importedTransactions = [];
        for (let i = 1; i < jsonData.length; i++) {
          const row = jsonData[i];
          if (!row || row.length === 0) continue;

          const date = row[dateIndex];
          const description = row[descriptionIndex] || '';
          let amount = parseFloat(row[amountIndex]) || 0;
          const category = row[categoryIndex] || '';
          const type = row[typeIndex] || '';

          // Skip if no description or amount
          if (!description || amount === 0) continue;

          // Format date
          let formattedDate;
          if (typeof date === 'number') {
            formattedDate = XLSX.SSF.format('yyyy-mm-dd', date);
          } else if (date instanceof Date) {
            formattedDate = date.toISOString().split('T')[0];
          } else {
            formattedDate = date.toString();
          }

          // Determine transaction type if not specified
          let transactionType = type;
          if (!transactionType) {
            transactionType = amount >= 0 ? 'Income' : 'Expense';
          }

          importedTransactions.push({
            id: Date.now() + i,
            date: formattedDate,
            description: description.toString(),
            amount: amount,
            type: transactionType,
            category: category.toString() || 'Other Expenses',
            originalDescription: description.toString()
          });
        }

        if (importedTransactions.length > 0) {
          setActualTransactions(importedTransactions);
          localStorage.setItem('importedTransactions', JSON.stringify(importedTransactions));
          alert(`Successfully imported ${importedTransactions.length} transactions from Excel!`);
        } else {
          alert('No valid transactions found in the Excel file.');
        }
      } catch (error) {
        console.error('Error importing transactions file:', error);
        alert('Error importing transactions file. Please make sure it\'s a valid Excel file with the correct columns.');
      }
    };
    
    reader.onerror = () => {
      alert('Error reading file. Please try again.');
    };
    
    reader.readAsArrayBuffer(file);
    event.target.value = '';
  };

  // Load sample data
  const loadSampleData = () => {
    // Sample budget data
    const sampleBudget = [
      { id: 1, category: 'Revenue', amount: 300000, description: 'Projected annual revenue' },
      { id: 2, category: 'Personnel & Salaries', amount: 150000, description: 'Staff salaries and benefits' },
      { id: 3, category: 'Equipment & Supplies', amount: 25000, description: 'Office equipment and supplies' },
      { id: 4, category: 'Travel & Transportation', amount: 15000, description: 'Program travel expenses' },
      { id: 5, category: 'Materials & Printing', amount: 12000, description: 'Educational materials' },
      { id: 6, category: 'Facility Costs', amount: 36000, description: 'Rent and utilities' },
      { id: 7, category: 'Professional Services', amount: 20000, description: 'Legal and accounting' },
      { id: 8, category: 'Administrative Costs', amount: 18000, description: 'Office administration' },
      { id: 9, category: 'Program Expenses', amount: 40000, description: 'Direct program costs' },
      { id: 10, category: 'Fundraising Costs', amount: 15000, description: 'Fundraising events and materials' },
      { id: 11, category: 'Other Expenses', amount: 10000, description: 'Miscellaneous expenses' }
    ];

    // Sample actual transactions (simplified for demo)
    const sampleTransactions = [
      { id: 1, date: '2024-01-15', description: 'Q1 Grant', amount: 75000, type: 'Income', category: 'Grants' },
      { id: 2, date: '2024-02-01', description: 'Staff Salaries', amount: -37500, type: 'Expense', category: 'Personnel & Salaries' },
      { id: 3, date: '2024-02-05', description: 'Office Supplies', amount: -5200, type: 'Expense', category: 'Equipment & Supplies' },
      { id: 4, date: '2024-02-10', description: 'Conference Travel', amount: -3200, type: 'Expense', category: 'Travel & Transportation' },
      { id: 5, date: '2024-02-15', description: 'Printing Materials', amount: -2800, type: 'Expense', category: 'Materials & Printing' },
      { id: 6, date: '2024-02-20', description: 'Monthly Rent', amount: -9000, type: 'Expense', category: 'Facility Costs' },
      { id: 7, date: '2024-02-25', description: 'Accounting Services', amount: -5000, type: 'Expense', category: 'Professional Services' },
      { id: 8, date: '2024-03-01', description: 'Individual Donations', amount: 25000, type: 'Income', category: 'Donations' },
      { id: 9, date: '2024-03-05', description: 'Office Administration', amount: -4500, type: 'Expense', category: 'Administrative Costs' },
      { id: 10, date: '2024-03-10', description: 'Program Materials', amount: -8500, type: 'Expense', category: 'Program Expenses' }
    ];

    setBudgetData(sampleBudget);
    setActualTransactions(sampleTransactions);
    
    // Set date range for sample data (Q1)
    const sampleStart = new Date('2024-01-01');
    const sampleEnd = new Date('2024-03-31');
    
    setStartDate(sampleStart.toISOString().split('T')[0]);
    setEndDate(sampleEnd.toISOString().split('T')[0]);
    setTimePeriod('custom');
    
    alert('Sample data loaded successfully! You can now see the budget vs actual comparison.');
  };

  // Export comparison to Excel
  const exportToExcel = () => {
    const comparison = calculateComparison();

    const excelData = [
      ['Budget vs Actual Dashboard', '', '', '', '', ''],
      ['Period:', `${startDate} to ${endDate}`, '', '', '', ''],
      ['Generated on:', new Date().toLocaleDateString(), '', '', '', ''],
      ['', '', '', '', '', ''],
      ['Category', 'Budget', 'Actual', 'Variance ($)', 'Variance (%)', 'Status'],
      ...comparison.map(item => [
        item.category,
        item.budget,
        item.actual,
        item.variance,
        `${item.variancePercent.toFixed(1)}%`,
        item.type === 'revenue' 
          ? (item.variance >= 0 ? 'Above Projection' : 'Below Projection')
          : (item.variance >= 0 ? 'Under Budget' : 'Over Budget')
      ]),
      ['', '', '', '', '', ''],
      ['Summary', '', '', '', '', ''],
      ['Total Budgeted Revenue:', comparison.find(c => c.category === 'Revenue')?.budget || 0, '', '', '', ''],
      ['Total Actual Revenue:', comparison.find(c => c.category === 'Revenue')?.actual || 0, '', '', '', ''],
      ['Total Budgeted Expenses:', comparison.filter(c => c.type === 'expense').reduce((sum, item) => sum + item.budget, 0), '', '', '', ''],
      ['Total Actual Expenses:', comparison.filter(c => c.type === 'expense').reduce((sum, item) => sum + item.actual, 0), '', '', '', '']
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(excelData);
    const colWidths = [
      { wch: 25 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 20 }
    ];
    worksheet['!cols'] = colWidths;

    // Add merges for headers
    if (!worksheet['!merges']) worksheet['!merges'] = [];
    worksheet['!merges'].push({ s: { r: 0, c: 0 }, e: { r: 0, c: 5 } });

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Budget vs Actual');

    const fileName = `budget-vs-actual-${new Date().getTime()}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  // Export to JSON
  const exportToJson = () => {
    const comparison = calculateComparison();
    const exportData = {
      budgetData,
      actualTransactions: getFilteredTransactions(),
      comparison,
      period: `${startDate} to ${endDate}`,
      exportDate: new Date().toISOString(),
      version: '1.0'
    };
    
    const dataStr = JSON.stringify(exportData, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    
    const link = document.createElement('a');
    link.href = URL.createObjectURL(dataBlob);
    link.download = `budget-vs-actual-${new Date().getTime()}.json`;
    link.click();
  };

  // Clear all data
  const clearData = () => {
    if (window.confirm('Are you sure you want to clear all budget and transaction data?')) {
      setBudgetData([]);
      setActualTransactions([]);
      localStorage.removeItem('budgetVsActualBudget');
      localStorage.removeItem('importedTransactions');
    }
  };

  const comparison = calculateComparison();

  // Get variance color class
  const getVarianceColor = (variance, type) => {
    if (type === 'revenue') {
      return variance >= 0 ? 'positive' : 'negative';
    } else {
      return variance >= 0 ? 'positive' : 'negative';
    }
  };

  // Get variance icon
  const getVarianceIcon = (variance, type) => {
    if (type === 'revenue') {
      return variance >= 0 ? '📈' : '📉';
    } else {
      return variance >= 0 ? '✅' : '⚠️';
    }
  };

  return (
    <div className="page">
      <div className="page-header">
        <h1>Budget vs Actual Dashboard</h1>
        <p className="subtitle">Compare your budgeted amounts with actual performance and track variances</p>
      </div>
      
      <div className="page-content">
        {/* Import Guide */}
        <div className="card import-guide-card">
          <h3>📊 Understanding Budget vs Actual</h3>
          <div className="import-guide">
            <div className="guide-section">
              <p><strong>Key Metrics:</strong> Track how your actual revenue and expenses compare to your budget.</p>
              <p>Green = Favorable (Revenue above budget, Expenses below budget) • Red = Unfavorable</p>
            </div>

            <div className="guide-section">
              <h4>How to Get Started:</h4>
              <div className="guide-options">
                <div className="guide-option">
                  <strong>Option 1: Test with Sample Data</strong>
                  <p>Click "Load Sample Data" to see the dashboard with example budget and transactions.</p>
                </div>
                <div className="guide-option">
                  <strong>Option 2: Import Your Data</strong>
                  <p>Upload your budget and transactions using Excel files for easy data entry.</p>
                  <p>Budget Columns: Category,	Amount,	Description</p>
                  <p>Transactions Columns: Date,	Description,	Amount,	Category,	Type[income or expense]</p>
                </div>
              </div>
            </div>

            <div className="guide-section">
              <h4>Excel File Requirements:</h4>
              <div className="excel-requirements">
                <div className="requirement">
                  <strong>Budget File:</strong> Category, Amount, Description columns
                </div>
                <div className="requirement">
                  <strong>Transactions File:</strong> Date, Description, Amount, Category columns
                </div>
              </div>
            </div>

            <div className="guide-section">
              <h4>Color Coding:</h4>
              <ul>
                <li><span className="positive">🟢 Green:</span> Revenue above projection or Expenses under budget</li>
                <li><span className="negative">🔴 Red:</span> Revenue below projection or Expenses over budget</li>
                <li>📈 = Revenue exceeding expectations</li>
                <li>📉 = Revenue below expectations</li>
                <li>✅ = Expenses within budget</li>
                <li>⚠️ = Expenses over budget</li>
              </ul>
            </div>
          </div>
        </div>

        {/* Controls Section */}
        <div className="card">
          <h3>⚙️ Dashboard Settings</h3>
          <div className="controls-grid">
            <div className="form-group">
              <label>Time Period</label>
              <select 
                value={timePeriod}
                onChange={(e) => setTimePeriod(e.target.value)}
              >
                <option value="last30">Last 30 Days</option>
                <option value="last90">Last 90 Days</option>
                <option value="ytd">Year to Date</option>
                <option value="lastYear">Last Calendar Year</option>
                <option value="custom">Custom Range</option>
              </select>
            </div>
            
            {timePeriod === 'custom' && (
              <>
                <div className="form-group">
                  <label>Start Date</label>
                  <input 
                    type="date"
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                  />
                </div>
                
                <div className="form-group">
                  <label>End Date</label>
                  <input 
                    type="date"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                  />
                </div>
              </>
            )}
          </div>
          
          <div className="import-export-controls">
            <button onClick={loadSampleData} className="card-btn card-btn-secondary">
              🧪 Load Sample Data
            </button>
            
            <label htmlFor="budget-excel-import" className="card-btn card-btn-secondary">
              📋 Import Budget (Excel)
            </label>
            <input
              id="budget-excel-import"
              type="file"
              accept=".xlsx,.xls,.csv"
              onChange={importBudgetFromExcel}
              style={{ display: 'none' }}
            />
            
            {/* UPDATED: Changed from JSON to Excel import for transactions */}
            <label htmlFor="transactions-excel-import" className="card-btn card-btn-secondary">
              💰 Import Transactions (Excel)
            </label>
            <input
              id="transactions-excel-import"
              type="file"
              accept=".xlsx,.xls,.csv"
              onChange={importTransactionsFromExcel}
              style={{ display: 'none' }}
            />
            
            <button onClick={exportToJson} className="card-btn card-btn-secondary">
              💾 Export to JSON
            </button>
            
            <button onClick={exportToExcel} className="card-btn card-btn-primary">
              📊 Export to Excel
            </button>
            
            <button onClick={clearData} className="card-btn card-btn-danger">
              🗑️ Clear Data
            </button>
          </div>
        </div>

        {/* Budget Input Section */}
        <div className="card">
          <div className="card-header">
            <h3>💰 Budget Setup</h3>
            <button onClick={addBudgetItem} className="card-btn">
              + Add Budget Item
            </button>
          </div>
          
          <div className="budget-items">
            {budgetData.map((item, index) => (
              <div key={item.id} className="budget-item">
                <div className="budget-item-header">
                  <h4>Budget Item #{index + 1}</h4>
                  <button 
                    onClick={() => removeBudgetItem(item.id)}
                    className="remove-btn"
                  >
                    ×
                  </button>
                </div>
                
                <div className="budget-item-fields">
                  <div className="form-group">
                    <label>Category</label>
                    <select 
                      value={item.category}
                      onChange={(e) => updateBudgetItem(item.id, 'category', e.target.value)}
                    >
                      <option value="">Select a category</option>
                      <option value="Revenue">Revenue</option>
                      {budgetCategories.map(category => (
                        <option key={category} value={category}>{category}</option>
                      ))}
                    </select>
                  </div>
                  
                  <div className="form-group">
                    <label>Description</label>
                    <input 
                      type="text"
                      value={item.description}
                      onChange={(e) => updateBudgetItem(item.id, 'description', e.target.value)}
                      placeholder="Describe this budget item..."
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Budget Amount ($)</label>
                    <input 
                      type="number"
                      value={item.amount}
                      onChange={(e) => updateBudgetItem(item.id, 'amount', parseFloat(e.target.value) || 0)}
                      step="0.01"
                      min="0"
                    />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Budget vs Actual Comparison */}
        {(budgetData.length > 0 || actualTransactions.length > 0) && (
          <div className="card">
            <h3>📈 Budget vs Actual Comparison</h3>
            <div className="statement-period">
              <strong>Period:</strong> {startDate} to {endDate}
            </div>
            
            <div className="comparison-table">
              <div className="table-header">
                <div>Category</div>
                <div>Budget</div>
                <div>Actual</div>
                <div>Variance ($)</div>
                <div>Variance (%)</div>
                <div>Status</div>
              </div>
              
              {comparison
                .filter(item => item.budget > 0 || item.actual > 0)
                .map((item, index) => (
                <div key={index} className="table-row">
                  <div className="category">{item.category}</div>
                  <div>${item.budget.toFixed(2)}</div>
                  <div>${item.actual.toFixed(2)}</div>
                  <div className={`variance ${getVarianceColor(item.variance, item.type)}`}>
                    {item.variance >= 0 ? '+' : ''}{item.variance.toFixed(2)}
                  </div>
                  <div className={`variance ${getVarianceColor(item.variance, item.type)}`}>
                    {item.variancePercent >= 0 ? '+' : ''}{item.variancePercent.toFixed(1)}%
                  </div>
                  <div className={`status ${getVarianceColor(item.variance, item.type)}`}>
                    {getVarianceIcon(item.variance, item.type)} {' '}
                    {item.type === 'revenue' 
                      ? (item.variance >= 0 ? 'Above Projection' : 'Below Projection')
                      : (item.variance >= 0 ? 'Under Budget' : 'Over Budget')
                    }
                  </div>
                </div>
              ))}
            </div>

            {/* Summary Statistics */}
            <div className="summary-stats">
              <div className="stat-item">
                <div className="stat-label">Total Budgeted</div>
                <div className="stat-value">
                  ${comparison.reduce((sum, item) => sum + item.budget, 0).toFixed(2)}
                </div>
              </div>
              <div className="stat-item">
                <div className="stat-label">Total Actual</div>
                <div className="stat-value">
                  ${comparison.reduce((sum, item) => sum + item.actual, 0).toFixed(2)}
                </div>
              </div>
              <div className="stat-item">
                <div className="stat-label">Net Variance</div>
                <div className={`stat-value ${comparison.reduce((sum, item) => sum + item.variance, 0) >= 0 ? 'positive' : 'negative'}`}>
                  ${comparison.reduce((sum, item) => sum + item.variance, 0).toFixed(2)}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Data Status */}
        <div className="card">
          <h3>📋 Data Status</h3>
          <div className="data-status-grid">
            <div className="status-item">
              <div className="status-value">{budgetData.length}</div>
              <div className="status-label">Budget Items Loaded</div>
            </div>
            <div className="status-item">
              <div className="status-value">{actualTransactions.length}</div>
              <div className="status-label">Total Transactions</div>
            </div>
            <div className="status-item">
              <div className="status-value">{getFilteredTransactions().length}</div>
              <div className="status-label">Filtered Transactions</div>
            </div>
            <div className="status-item">
              <div className="status-value">
                {comparison.filter(item => item.budget > 0).length}
              </div>
              <div className="status-label">Categories with Budget</div>
            </div>
          </div>
        </div>

        {budgetData.length === 0 && actualTransactions.length === 0 && (
          <div className="empty-state card">
            <h3>Start Monitoring Your Budget Performance</h3>
            <p>Load sample data or import your budget and transactions to see budget vs actual comparisons.</p>
            <ul className="budget-tips">
              <li>💡 Set up your annual budget by category</li>
              <li>💡 Import actual transactions from Excel spreadsheets</li>
              <li>💡 Track variances with color-coded indicators</li>
              <li>💡 Identify areas of over-spending or under-performance</li>
              <li>💡 Export reports for board meetings and financial reviews</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default BudgetVsActualDashboard;