import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import './Sidebar.css';

const Sidebar = ({ isOpen, isMobile, onToggle, onClose }) => {
  const location = useLocation();

  const menuItems = [
    { path: '/', label: 'Home', icon: '🏠' },
    { path: '/grant-toolbox', label: 'Grant Toolbox', icon: '🧰' },
    { path: '/bookkeeper-toolbox', label: 'Bookkeeper Toolbox', icon: '📊' },
    { path: '/datathon-projects', label: 'Datathon Projects', icon: '📈' },
    { path: 'https://github.com/budlib', label: 'BudLib', icon: '📚', external: true }
  ];

  return (
    <>
      {isMobile && (
        <button className="mobile-menu-btn" onClick={onToggle}>
          ☰
        </button>
      )}
      
      <div className={`sidebar ${isOpen ? 'open' : ''} ${isMobile ? 'mobile' : ''}`}>
        <div className="sidebar-header">
          <h2>Michael's CivicTech Sandbox</h2>
          {isMobile && (
            <button className="close-btn" onClick={onClose}>
              ×
            </button>
          )}
        </div>
        
        <nav className="sidebar-nav">
          {menuItems.map((item) => (
            item.external ? (
              <a
                key={item.path}
                href={item.path}
                target="_blank"
                rel="noopener noreferrer"
                className="nav-item"
                onClick={() => isMobile && onClose()}
              >
                <span className="nav-icon">{item.icon}</span>
                <span className="nav-label">{item.label}</span>
                <span className="external-indicator">↗</span>
              </a>
            ) : (
              <Link
                key={item.path}
                to={item.path}
                className={`nav-item ${location.pathname === item.path ? 'active' : ''}`}
                onClick={() => isMobile && onClose()}
              >
                <span className="nav-icon">{item.icon}</span>
                <span className="nav-label">{item.label}</span>
              </Link>
            )
          ))}
        </nav>
        
        <div className="sidebar-footer">
          <p>Building tools for civic good</p>
        </div>
      </div>
      
      {isMobile && isOpen && (
        <div className="sidebar-overlay" onClick={onClose} />
      )}
    </>
  );
};

export default Sidebar;