import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import './Pages.css';

const PettyCashManager = () => {
  const [transactions, setTransactions] = useState([]);
  const [currentBalance, setCurrentBalance] = useState(0);
  const [startingBalance, setStartingBalance] = useState(0);

  // Load from localStorage on component mount
  React.useEffect(() => {
    const savedPettyCash = localStorage.getItem('pettyCashData');
    if (savedPettyCash) {
      try {
        const parsedData = JSON.parse(savedPettyCash);
        setTransactions(parsedData.transactions || []);
        setCurrentBalance(parsedData.currentBalance || 0);
        setStartingBalance(parsedData.startingBalance || 0);
      } catch (error) {
        console.error('Error loading saved petty cash data:', error);
      }
    }
  }, []);

  // Save to localStorage whenever data changes
  React.useEffect(() => {
    const pettyCashData = {
      transactions: transactions,
      currentBalance: currentBalance,
      startingBalance: startingBalance,
      lastUpdated: new Date().toISOString()
    };
    localStorage.setItem('pettyCashData', JSON.stringify(pettyCashData));
  }, [transactions, currentBalance, startingBalance]);

  const addTransaction = () => {
    const newTransaction = {
      id: Date.now(),
      date: new Date().toISOString().split('T')[0],
      description: '',
      amount: 0,
      type: 'disbursement',
      balanceAfter: currentBalance
    };
    setTransactions([...transactions, newTransaction]);
  };

  const updateTransaction = (id, field, value) => {
    const updatedTransactions = transactions.map(transaction => {
      if (transaction.id === id) {
        return { ...transaction, [field]: value };
      }
      return transaction;
    });
    
    setTransactions(updatedTransactions);
    recalculateBalances(updatedTransactions, startingBalance);
  };

  const removeTransaction = (id) => {
    const filteredTransactions = transactions.filter(transaction => transaction.id !== id);
    setTransactions(filteredTransactions);
    recalculateBalances(filteredTransactions, startingBalance);
  };

  const recalculateBalances = (transactionsList, startBalance) => {
    let runningBalance = startBalance;
    const updatedTransactions = transactionsList.map(transaction => {
      if (transaction.type === 'disbursement') {
        runningBalance -= transaction.amount;
      } else {
        runningBalance += transaction.amount;
      }
      return { ...transaction, balanceAfter: runningBalance };
    });
    
    setTransactions(updatedTransactions);
    setCurrentBalance(runningBalance);
  };

  const updateStartingBalance = (newBalance) => {
    const numericBalance = parseFloat(newBalance) || 0;
    setStartingBalance(numericBalance);
    recalculateBalances(transactions, numericBalance);
  };

  // Download Template Excel Sheet
  const downloadTemplateExcel = () => {
    const templateData = [
      ['PETTY CASH TEMPLATE - IMPORT GUIDE', '', '', '', ''],
      ['', '', '', '', ''],
      ['INSTRUCTIONS:', '', '', '', ''],
      ['1. Set your starting balance in cell B8 (currently $100.00)', '', '', '', ''],
      ['2. Add your transactions below the header row (row 11)', '', '', '', ''],
      ['3. For Type column, use exactly: "Disbursement" or "Replenishment"', '', '', '', ''],
      ['4. Save this file and import it back into the Petty Cash Manager', '', '', '', ''],
      ['', '', '', '', ''],
      ['Starting Balance:', '100.00', '', '', ''],
      ['', '', '', '', ''],
      ['Date', 'Description', 'Type', 'Amount', 'Balance After'],
      ['2023-12-01', 'Office supplies - pens and notebooks', 'Disbursement', '25.50', '74.50'],
      ['2023-12-02', 'Coffee for team meeting', 'Disbursement', '15.75', '58.75'],
      ['2023-12-03', 'Cash replenishment from main account', 'Replenishment', '100.00', '158.75'],
      ['2023-12-04', 'Postage stamps', 'Disbursement', '12.00', '146.75'],
      ['', '', '', '', ''],
      ['IMPORTANT NOTES:', '', '', '', ''],
      ['- Keep the header row exactly as shown (Date, Description, Type, Amount, Balance After)', '', '', '', ''],
      ['- Use YYYY-MM-DD format for dates (e.g., 2023-12-31)', '', '', '', ''],
      ['- Balance After column is optional - it will be auto-calculated on import', '', '', '', ''],
      ['- Delete the example rows (11-14) and add your own transactions', '', '', '', '']
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(templateData);
    const colWidths = [
      { wch: 25 }, { wch: 40 }, { wch: 15 }, { wch: 12 }, { wch: 15 }
    ];
    worksheet['!cols'] = colWidths;

    // Merge title cells
    if (!worksheet['!merges']) worksheet['!merges'] = [];
    worksheet['!merges'].push(
      { s: { r: 0, c: 0 }, e: { r: 0, c: 4 } },
      { s: { r: 2, c: 0 }, e: { r: 2, c: 4 } },
      { s: { r: 15, c: 0 }, e: { r: 15, c: 4 } }
    );

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Petty Cash Template');

    const fileName = `petty-cash-template.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  const downloadPettyCashAsExcel = () => {
    const excelData = [
      ['Petty Cash Log', '', '', '', ''],
      ['Generated on:', new Date().toLocaleDateString(), '', '', ''],
      ['Starting Balance:', `$${startingBalance.toFixed(2)}`, '', '', ''],
      ['Current Balance:', `$${currentBalance.toFixed(2)}`, '', '', ''],
      ['', '', '', '', ''],
      ['Date', 'Description', 'Type', 'Amount ($)', 'Balance After ($)'],
      ...transactions.map(transaction => [
        transaction.date,
        transaction.description,
        transaction.type === 'disbursement' ? 'Disbursement' : 'Replenishment',
        transaction.amount,
        transaction.balanceAfter
      ]),
      ['', '', '', '', ''],
      ['', '', '', 'Starting Balance:', `$${startingBalance.toFixed(2)}`],
      ['', '', '', 'Current Balance:', `$${currentBalance.toFixed(2)}`],
      ['', '', '', 'Difference:', `$${(currentBalance - startingBalance).toFixed(2)}`]
    ];

    const worksheet = XLSX.utils.aoa_to_sheet(excelData);
    const colWidths = [
      { wch: 12 }, { wch: 40 }, { wch: 15 }, { wch: 15 }, { wch: 15 }
    ];
    worksheet['!cols'] = colWidths;

    if (!worksheet['!merges']) worksheet['!merges'] = [];
    worksheet['!merges'].push({ s: { r: 0, c: 0 }, e: { r: 0, c: 4 } });

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Petty Cash Log');

    const fileName = `petty-cash-log-${new Date().getTime()}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  // FIXED: Improved import functionality
  const importPettyCashFromExcel = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        
        const worksheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { 
          header: 1,
          raw: false, // Get raw values to handle dates properly
          defval: '' 
        });
        
        console.log('Raw Excel data:', jsonData); // Debug log

        // Find the header row
        const headerRowIndex = jsonData.findIndex(row => 
          row && 
          row[0] && 
          String(row[0]).toLowerCase().includes('date') && 
          row[1] && 
          String(row[1]).toLowerCase().includes('description')
        );
        
        if (headerRowIndex === -1) {
          alert('Could not find the transaction data in the uploaded file. Please make sure you are using the template format.');
          return;
        }

        // Extract starting balance - look for "Starting Balance" in various formats
        let importedStartingBalance = 0;
        for (let i = 0; i < Math.min(headerRowIndex, 20); i++) {
          const row = jsonData[i];
          if (row && row[0] && String(row[0]).toLowerCase().includes('starting balance')) {
            const balanceValue = row[1] || row[2] || row[3] || row[4];
            importedStartingBalance = parseFloat(String(balanceValue).replace(/[$,]/g, '')) || 0;
            break;
          }
        }

        // If still no starting balance found, use default
        if (importedStartingBalance === 0) {
          importedStartingBalance = 100.00; // Default from template
        }

        // Extract transactions
        const importedTransactions = [];
        for (let i = headerRowIndex + 1; i < jsonData.length; i++) {
          const row = jsonData[i];
          
          // Stop if we hit an empty row or instruction row
          if (!row || row.length === 0 || !row[0]) {
            continue;
          }
          
          // Skip rows that are clearly instructions or headers
          if (String(row[0]).toLowerCase().includes('instruction') || 
              String(row[0]).toLowerCase().includes('important') ||
              String(row[0]).toLowerCase().includes('note')) {
            continue;
          }

          const [date, description, type, amount, balanceAfter] = row;
          
          // Skip if essential data is missing
          if (!date || !description || amount === undefined || amount === '') {
            continue;
          }

          // Parse the data with better error handling
          let transactionDate;
          try {
            // Handle Excel serial numbers and various date formats
            if (typeof date === 'number') {
              // Excel serial number
              const excelDate = XLSX.SSF.parse_date_code(date);
              transactionDate = `${excelDate.y}-${String(excelDate.m).padStart(2, '0')}-${String(excelDate.d).padStart(2, '0')}`;
            } else if (date instanceof Date) {
              // Date object
              transactionDate = date.toISOString().split('T')[0];
            } else {
              // String date - try to parse various formats
              const dateStr = String(date);
              if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
                transactionDate = dateStr;
              } else if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(dateStr)) {
                // Handle MM/DD/YYYY format
                const [month, day, year] = dateStr.split('/');
                transactionDate = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
              } else {
                // Fallback to today's date
                transactionDate = new Date().toISOString().split('T')[0];
              }
            }
          } catch (error) {
            console.warn('Error parsing date:', date, error);
            transactionDate = new Date().toISOString().split('T')[0];
          }

          const transactionType = String(type || '').toLowerCase().includes('replenishment') ? 'replenishment' : 'disbursement';
          
          let transactionAmount = 0;
          try {
            transactionAmount = Math.abs(parseFloat(String(amount).replace(/[$,]/g, '')) || 0);
          } catch (error) {
            console.warn('Error parsing amount:', amount, error);
            transactionAmount = 0;
          }

          // Only add if we have valid data
          if (transactionAmount > 0 && description.trim() !== '') {
            importedTransactions.push({
              id: Date.now() + i,
              date: transactionDate,
              description: String(description || '').trim(),
              amount: transactionAmount,
              type: transactionType,
              balanceAfter: 0 // Will be recalculated
            });
          }
        }

        if (importedTransactions.length > 0) {
          // Recalculate balances based on imported transactions
          recalculateBalances(importedTransactions, importedStartingBalance);
          alert(`Successfully imported ${importedTransactions.length} transactions with starting balance of $${importedStartingBalance.toFixed(2)}!`);
        } else {
          alert('No valid transactions found in the file. Please check that you have filled out the template correctly.');
        }
      } catch (error) {
        console.error('Error importing file:', error);
        alert('Error importing file. Please make sure you are using the template format and that the file is not corrupted.');
      }
    };
    
    reader.onerror = () => {
      alert('Error reading file. Please try again.');
    };
    
    reader.readAsArrayBuffer(file);
    event.target.value = '';
  };

  const resetPettyCash = () => {
    if (window.confirm('Are you sure you want to clear all petty cash data? This action cannot be undone.')) {
      setTransactions([]);
      setCurrentBalance(0);
      setStartingBalance(0);
      localStorage.removeItem('pettyCashData');
    }
  };

  const exportToJson = () => {
    const pettyCashData = {
      transactions: transactions,
      currentBalance: currentBalance,
      startingBalance: startingBalance,
      exportDate: new Date().toISOString(),
      version: '1.0'
    };
    
    const dataStr = JSON.stringify(pettyCashData, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    
    const link = document.createElement('a');
    link.href = URL.createObjectURL(dataBlob);
    link.download = `petty-cash-backup-${new Date().getTime()}.json`;
    link.click();
  };

  const importFromJson = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const importedData = JSON.parse(e.target.result);
        
        if (importedData.transactions && Array.isArray(importedData.transactions)) {
          setTransactions(importedData.transactions);
          setCurrentBalance(importedData.currentBalance || 0);
          setStartingBalance(importedData.startingBalance || 0);
          alert('Petty cash data successfully restored from backup!');
        } else {
          alert('Invalid backup file format.');
        }
      } catch (error) {
        console.error('Error importing backup:', error);
        alert('Error importing backup file. Please make sure it\'s a valid backup from this app.');
      }
    };
    
    reader.readAsText(file);
    event.target.value = '';
  };

  return (
    <div className="page">
      <div className="page-header">
        <h1>Petty Cash Manager</h1>
        <p className="subtitle">Track petty cash disbursements and maintain accurate cash balances</p>
      </div>
      
      <div className="page-content">
        {/* Balance Summary */}
        <div className="petty-cash-summary card">
          <div className="balance-display">
            <div className="balance-item">
              <label>Starting Balance</label>
              <input
                type="number"
                value={startingBalance}
                onChange={(e) => updateStartingBalance(e.target.value)}
                step="0.01"
                min="0"
              />
            </div>
            <div className="balance-item">
              <label>Current Balance</label>
              <div className="current-balance">${currentBalance.toFixed(2)}</div>
            </div>
            <div className="balance-item">
              <label>Difference</label>
              <div className={`difference ${currentBalance - startingBalance >= 0 ? 'positive' : 'negative'}`}>
                ${(currentBalance - startingBalance).toFixed(2)}
              </div>
            </div>
          </div>
        </div>

        {/* Import/Export Controls */}
        <div className="petty-cash-controls">
          <button onClick={addTransaction} className="card-btn">
            + Add Transaction
          </button>
          <button onClick={resetPettyCash} className="card-btn card-btn-secondary">
            Reset All Data
          </button>
          
          <div className="import-export-controls">
            <button onClick={downloadTemplateExcel} className="card-btn card-btn-secondary">
              📝 Download Template
            </button>
            
            <label htmlFor="petty-cash-excel-import" className="card-btn card-btn-secondary">
              📂 Import Excel
            </label>
            <input
              id="petty-cash-excel-import"
              type="file"
              accept=".xlsx,.xls"
              onChange={importPettyCashFromExcel}
              style={{ display: 'none' }}
            />
            
            <label htmlFor="petty-cash-json-import" className="card-btn card-btn-secondary">
              📂 Import Backup
            </label>
            <input
              id="petty-cash-json-import"
              type="file"
              accept=".json"
              onChange={importFromJson}
              style={{ display: 'none' }}
            />
            
            <button onClick={exportToJson} className="card-btn card-btn-secondary">
              💾 Backup to JSON
            </button>
            
            <button onClick={downloadPettyCashAsExcel} className="card-btn card-btn-primary">
              📊 Export to Excel
            </button>
          </div>
        </div>

        {/* Rest of the component remains the same */}
        <div className="transactions-list">
          {transactions.map((transaction, index) => (
            <div key={transaction.id} className="transaction-item card">
              <div className="transaction-header">
                <h4>Transaction #{index + 1}</h4>
                <button 
                  onClick={() => removeTransaction(transaction.id)}
                  className="remove-btn"
                >
                  ×
                </button>
              </div>
              
              <div className="transaction-fields">
                <div className="form-group">
                  <label>Date</label>
                  <input 
                    type="date"
                    value={transaction.date}
                    onChange={(e) => updateTransaction(transaction.id, 'date', e.target.value)}
                  />
                </div>
                
                <div className="form-group">
                  <label>Description</label>
                  <input 
                    type="text"
                    value={transaction.description}
                    onChange={(e) => updateTransaction(transaction.id, 'description', e.target.value)}
                    placeholder="Reason for disbursement or replenishment..."
                  />
                </div>
                
                <div className="form-group">
                  <label>Type</label>
                  <select 
                    value={transaction.type}
                    onChange={(e) => updateTransaction(transaction.id, 'type', e.target.value)}
                  >
                    <option value="disbursement">Disbursement</option>
                    <option value="replenishment">Replenishment</option>
                  </select>
                </div>
                
                <div className="transaction-numbers">
                  <div className="form-group">
                    <label>Amount ($)</label>
                    <input 
                      type="number"
                      value={transaction.amount}
                      onChange={(e) => updateTransaction(transaction.id, 'amount', parseFloat(e.target.value) || 0)}
                      step="0.01"
                      min="0"
                    />
                  </div>
                  
                  <div className="form-group">
                    <label>Balance After</label>
                    <div className="balance-after">
                      ${transaction.balanceAfter.toFixed(2)}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {transactions.length === 0 && (
          <div className="empty-state card">
            <h3>Start Managing Your Petty Cash</h3>
            <p>Click "Add Transaction" to begin tracking petty cash disbursements and replenishments.</p>
            <ul className="petty-cash-tips">
              <li>💡 Set your starting balance to match your physical cash</li>
              <li>💡 Record every disbursement with description and amount</li>
              <li>💡 Track replenishments when adding more cash to the fund</li>
              <li>💡 <strong>Use "Download Template" to create transactions in Excel</strong></li>
              <li>💡 Fill the template and import it back into the app</li>
              <li>💡 Export to Excel for reporting and reconciliation</li>
              <li>💡 Use backups to prevent data loss</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default PettyCashManager;